INSERT INTO `agendas` (`id`, `title`, `slug`, `excerpt`, `content`, `location`, `image`, `status`, `starts_at`, `ends_at`, `created_at`, `updated_at`) VALUES (3,'{\"id\":\"Seminar Transformasi Human Capital\",\"en\":\"Human Capital Transformation Seminar\"}','seminar-transformasi-human-capital','{\"id\":\"Kegiatan 2 hari di Jakarta Selatan, DKI Jakarta, terbuka untuk peserta umum dan kelompok perusahaan.\",\"en\":\"A 2-day programme in Jakarta Selatan, DKI Jakarta, open to individual and corporate participants.\"}','{\"id\":\"<p>Kegiatan ini dirancang agar peserta tidak hanya menerima penjelasan, tetapi langsung mempraktikkannya pada kasus yang mereka bawa dari tempat kerja masing-masing. Porsi latihan lebih besar dibanding pemaparan.</p><h2>Materi yang dibahas</h2><ul><li>Dasar dan kerangka kerja yang dipakai di lapangan.</li><li>Studi kasus dari industri peserta sendiri.</li><li>Latihan terbimbing dengan umpan balik langsung dari pengajar.</li><li>Penyusunan rencana tindak lanjut untuk dibawa pulang.</li></ul><h2>Siapa yang sebaiknya hadir</h2><p>Praktisi, pengawas, dan staf yang menjalankan fungsi terkait secara langsung, termasuk mereka yang sedang disiapkan untuk peran tersebut.</p><h2>Keterangan tambahan</h2><p>Peserta memperoleh modul, konsumsi selama kegiatan, dan sertifikat kepesertaan. Untuk pendaftaran kelompok di atas lima orang, silakan hubungi tim kami lebih dulu.</p>\",\"en\":\"<p>This programme is designed so participants do more than listen: they practise directly on cases brought from their own workplaces. Exercise time outweighs presentation time.</p><h2>What will be covered</h2><ul><li>The foundations and framework used in the field.</li><li>Case studies from participants\' own industries.</li><li>Guided practice with direct instructor feedback.</li><li>Building a follow-up action plan to take home.</li></ul><h2>Who should attend</h2><p>Practitioners, supervisors, and staff who run the related function directly, including those being prepared for such a role.</p><h2>Additional information</h2><p>Participants receive modules, refreshments during the event, and a certificate of attendance. For group registration above five people, please contact our team in advance.</p>\"}','Jakarta Selatan, DKI Jakarta','banners/fiaagkurioh1qjmqsbvquepqi2y2qhbbbkp9z8uq.webp','published','2026-05-09 01:30:00','2026-05-10 09:30:00','2026-09-14 07:43:24','2026-09-14 08:15:12'),(4,'{\"id\":\"Pelatihan Ahli K3 Umum Angkatan 24\",\"en\":\"General Safety Expert Training Batch 24\"}','pelatihan-ahli-k3-umum-angkatan-24','{\"id\":\"Kegiatan 3 hari di Jakarta Selatan, DKI Jakarta, terbuka untuk peserta umum dan kelompok perusahaan.\",\"en\":\"A 3-day programme in Jakarta Selatan, DKI Jakarta, open to individual and corporate participants.\"}','{\"id\":\"<p>Kegiatan ini dirancang agar peserta tidak hanya menerima penjelasan, tetapi langsung mempraktikkannya pada kasus yang mereka bawa dari tempat kerja masing-masing. Porsi latihan lebih besar dibanding pemaparan.</p><h2>Materi yang dibahas</h2><ul><li>Dasar dan kerangka kerja yang dipakai di lapangan.</li><li>Studi kasus dari industri peserta sendiri.</li><li>Latihan terbimbing dengan umpan balik langsung dari pengajar.</li><li>Penyusunan rencana tindak lanjut untuk dibawa pulang.</li></ul><h2>Siapa yang sebaiknya hadir</h2><p>Praktisi, pengawas, dan staf yang menjalankan fungsi terkait secara langsung, termasuk mereka yang sedang disiapkan untuk peran tersebut.</p><h2>Keterangan tambahan</h2><p>Peserta memperoleh modul, konsumsi selama kegiatan, dan sertifikat kepesertaan. Untuk pendaftaran kelompok di atas lima orang, silakan hubungi tim kami lebih dulu.</p>\",\"en\":\"<p>This programme is designed so participants do more than listen: they practise directly on cases brought from their own workplaces. Exercise time outweighs presentation time.</p><h2>What will be covered</h2><ul><li>The foundations and framework used in the field.</li><li>Case studies from participants\' own industrie