INSERT INTO `blog_posts` (`id`, `blog_category_id`, `author_id`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `banner_image`, `location`, `status`, `is_featured`, `views`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES (1,2,NULL,'{\"id\":\"Mengapa Analisis Kebutuhan Pelatihan Sering Dilewati\",\"en\":\"Why Training Needs Analysis Gets Skipped\"}','mengapa-analisis-kebutuhan-pelatihan-sering-dilewati','{\"id\":\"Banyak perusahaan memilih program pelatihan dari katalog sebelum tahu masalah apa yang hendak diselesaikan.\",\"en\":\"Many companies pick training from a catalogue before knowing which problem they intend to solve.\"}','{\"id\":\"<p>Banyak perusahaan memilih program pelatihan dari katalog sebelum tahu masalah apa yang hendak diselesaikan.</p><h2>Masalah yang sering terjadi</h2><p>Dalam pendampingan kami di berbagai perusahaan, persoalan ini hampir selalu muncul dalam bentuk yang sama: keputusan diambil lebih dulu, alasannya disusun belakangan. Akibatnya sumber daya terpakai untuk memperbaiki gejala, sementara penyebabnya tetap di tempat.</p><h3>Yang perlu diperhatikan</h3><ul><li>Ukuran keberhasilan tidak disepakati sebelum program dimulai.</li><li>Data yang sudah dimiliki perusahaan jarang dilihat kembali.</li><li>Pihak yang paling terdampak tidak dilibatkan sejak awal.</li></ul><h2>Cara memperbaikinya</h2><p>Langkah pertama selalu memperjelas apa yang hendak berubah dan bagaimana perubahan itu akan terlihat. Tanpa itu, program apa pun sulit dinilai berhasil atau tidak, dan pembahasannya berhenti pada selera.</p><h2>Apa yang berubah setelah diterapkan</h2><p>Perubahan yang paling cepat terasa biasanya bukan pada angka besar, melainkan pada berkurangnya pekerjaan ulang dan perdebatan berulang. Angka menyusul kemudian, setelah kebiasaan barunya bertahan beberapa bulan.</p><h2>Kesimpulan</h2><p>Tidak ada pendekatan tunggal yang cocok untuk semua organisasi. Namun memulai dari pertanyaan yang tepat hampir selalu lebih murah daripada memperbaiki program yang sudah terlanjur berjalan ke arah yang salah.</p>\",\"en\":\"<p>Many companies pick training from a catalogue before knowing which problem they intend to solve.</p><h2>The problem we keep seeing</h2><p>Across the companies we work with, this issue shows up in almost the same shape every time: the decision comes first and the reasoning is assembled afterwards. Resources then go into treating symptoms while the cause stays put.</p><h3>What to watch for</h3><ul><li>Success measures are not agreed before the programme starts.</li><li>Data the company already holds is rarely revisited.</li><li>Those most affected are not involved from the outset.</li></ul><h2>How to put it right</h2><p>The first step is always to make clear what should change and how that change will be visible. Without it, no programme can be judged a success, and the discussion stops at taste.</p><h2>What changes once it is applied</h2><p>The fastest-felt change is usually not in the headline numbers but in less rework and fewer repeated arguments. The numbers follow later, once the new habit has held for a few months.</p><h2>Conclusion</h2><p>No single approach suits every organisation. But starting from the right question is almost always cheaper than fixing a programme already running in the wrong direction.</p>\"}','blog/6npxygel4tqdtgcv8dd7vu6gl0dji9popp6dlbft.webp',NULL,'Jakarta Selatan, DKI Jakarta','published',1,125,'2026-09-11 02:00:00',NULL,NULL,'2026-09-14 08:15:06','2026-09-16 07:46:08'),(2,1,NULL,'{\"id\":\"Membaca Kisi Sembilan Kotak Tanpa Salah Tafsir\",\"en\":\"Reading the Nine-Box Grid Without Misreading It\"}','membaca-kisi-sembilan-kotak-tanpa-salah-tafsir','{\"id\":\"Kisi sembilan kotak bukan alat untuk memberi label pada orang, melainkan untuk menentukan perlakuan pengembangan.\",\"en\":\"The nine-box grid is not a tool for labelling people but for deciding development treatment.\"}','{\"id\":\"<p>Kisi sembilan kotak bukan alat untuk memberi label pada orang, melainkan untuk menentukan perlakuan pengembangan.</p><h2>Masalah yang sering terjadi</h2><p>Dalam pendampingan kami di berbagai perusahaan, persoalan ini hampir selalu muncul dalam bentuk yang sama: keputusan diambil lebih dulu, alasannya disusun belakangan. Akibatnya sumber daya terpakai untuk memperbaiki gejala, sementara penyebabnya tetap di tempat.</p><h3>Yang perlu diperhatikan</h3><ul><li>Ukuran keberhasilan tidak disepakati sebelum program dimulai.</li><li>Data yang sudah dimiliki perusahaan jarang dilihat kembali.</li><li>Pihak yang paling terdampak tidak dilibatkan sejak awal.</li></ul><h2>Cara memperbaikinya</h2><p>Langkah pertama selalu memperjelas apa yang hendak berubah dan bagaimana perubahan itu akan terlihat. Tanpa itu, program apa pun sulit dinilai berhasil atau tidak, dan pembahasannya berhenti pada selera.</p><h2>Apa yang berubah setelah diterapkan</h2><p>Perubahan yang paling cepat terasa biasanya bukan pada angka besar, melainkan pada berkurangnya pekerjaan ulang dan perdebatan berulang. Angka menyusul kemudian, setelah kebiasaan barunya bertahan beberapa bulan.</p><h2>Kesimpulan</h2><p>Tidak ada pendekatan tunggal yang cocok untuk semua organisasi. Namun memulai dari pertanyaan yang tepat hampir selalu lebih murah daripada memperbaiki program yang sudah terlanjur berjalan ke arah yang salah.</p>\",\"en\":\"<p>The nine-box grid is not a tool for labelling people but for deciding development treatment.</p><h2>The problem we keep seeing</h2><p>Across the companies we work with, this issue shows up in almost the same shape every time: the decision comes first and the reasoning is assembled afterwards. Resources then go into treating symptoms while the cause stays put.</p><h3>What to watch for</h3><ul><li>Success measures are not agreed before the programme starts.</li><li>Data the company already holds is rarely revisited.</li><li>Those most affected are not involved from the outset.</li></ul><h2>How to put it right</h2><p>The first step is always to make clear what should change and how that change will be visible. Without it, no programme can be judged a success, and the discussion stops at taste.</p><h2>What changes once it is applied</h2><p>The fastest-felt change is usually not in the headline numbers but in less rework and fewer repeated arguments. The numbers follow later, once the new habit has held for a few months.</p><h2>Conclusion</h2><p>No single approach suits every organisation. But starting from the right question is almost always cheaper than fixing a programme already running in the wrong direction.</p>\"}','blog/dbfav0437r6bk5jr2shxtpayeznbv0yrjy0ldc4u.webp',NULL,'Bandung, Jawa Barat','published',1,158,'2026-09-04 02:00:00',NULL,NULL,'2026-09-14 08:15:06','2026-09-14 08:18:48'),(3,3,NULL,'{\"id\":\"Sertifikasi BNSP: Apa yang Diuji dan Apa yang Tidak\",\"en\":\"BNSP Certification: What Is Assessed and What Is Not\"}','sertifikasi-bnsp-apa-yang-diuji-dan-apa-yang-tidak','{\"id\":\"Sertifikasi kompetensi menguji bukti kerja, bukan hafalan teori. Perbedaan ini mengubah cara peserta perlu bersiap.\",\"en\":\"Competency certification assesses work evidence, not memorised theory. That difference changes how participants should prepare.\"}','{\"id\":\"<p>Sertifikasi kompetensi menguji bukti kerja, bukan hafalan teori. Perbedaan ini mengubah cara peserta perlu bersiap.</p><h2>Masalah yang sering terjadi</h2><p>Dalam pendampingan kami di berbagai perusahaan, persoalan ini hampir selalu muncul dalam bentuk yang sama: keputusan diambil lebih dulu, alasannya disusun belakangan. Akibatnya sumber daya terpakai untuk memperbaiki gejala, sementara penyebabnya tetap di tempat.</p><h3>Yang perlu diperhatikan</h3><ul><li>Ukuran keberhasilan tidak disepakati sebelum program dimulai.</li><li>Data yang sudah dimiliki perusahaan jarang dilihat kembali.</li><li>Pihak yang paling terdampak tidak dilibatkan sejak awal.</li></ul><h2>Cara memperbaikinya</h2><p>Langkah pertama selalu memperjelas apa yang hendak berubah dan bagaimana perubahan itu akan terlihat. Tanpa itu, program apa pun sulit dinilai berhasil atau tidak, dan pembahasannya berhenti pada selera.</p><h2>Apa yang berubah setelah diterapkan</h2><p>Perubahan yang paling cepat terasa biasanya bukan pada angka besar, melainkan pada berkurangnya pekerjaan ulang dan perdebatan berulang. Angka menyusul kemudian, setelah kebiasaan barunya bertahan beberapa bulan.</p><h2>Kesimpulan</h2><p>Tidak ada pendekatan tunggal yang cocok untuk semua organisasi. Namun memulai dari pertanyaan yang tepat hampir selalu lebih murah daripada memperbaiki program yang sudah terlanjur berjalan ke arah yang salah.</p>\",\"en\":\"<p>Competency certification assesses work evidence, not memorised theory. That difference changes how participants should prepare.</p><h2>The problem we keep seeing</h2><p>Across the companies we work with, this issue shows up in almost the same shape every time: the decision comes first and the reasoning is assembled afterwards. Resources then go into treating symptoms while the cause stays put.</p><h3>What to watch for</h3><ul><li>Success measures are not agreed before the programme starts.</li><li>Data the company already holds is rarely revisited.</li><li>Those most affected are not involved from the outset.</li></ul><h2>How to put it right</h2><p>The first step is always to make clear what should change and how that change will be visible. Without it, no programme can be judged a success, and the discussion stops at taste.</p><h2>What changes once it is applied</h2><p>The fastest-felt change is usually not in the headline numbers but in less rework and fewer repeated arguments. The numbers follow later, once the new habit has held for a few months.</p><h2>Conclusion</h2><p>No single approach suits every organisation. But starting from the right question is almost always cheaper than fixing a programme already running in the wrong direction.</p>\"}','blog/dlgnz1fddegc7dcvw1f6dninz8yv7eyt8kjdzd4i.webp',NULL,'Jakarta Pusat, DKI Jakarta','published',1,194,'2026-08-28 02:00:00',NULL,NULL,'2026-09-14 08:15:06','2026-09-14 08:15:06'),(4,2,NULL,'{\"id\":\"Supervisor Baru dan Jebakan Keahlian Teknis\",\"en\":\"New Supervisors and the Technical Skill Trap\"}','supervisor-baru-dan-jebakan-keahlian-teknis','{\"id\":\"Orang terbaik di satu pekerjaan belum tentu menjadi pemimpin terbaik bagi orang yang mengerjakannya.\",\"en\":\"The best person at a job is not automatically the best leader of the people doing it.\"}','{\"id\":\"<p>Orang terbaik di satu pekerjaan belum tentu menjadi pemimpin terbaik bagi orang yang mengerjakannya.</p><h2>Masalah yang sering terjadi</h2><p>Dalam pendampingan kami di berbagai perusahaan, persoalan ini hampir selalu muncul dalam bentuk yang sama: keputusan diambil lebih dulu, alasannya disusun belakangan. Akibatnya sumber daya terpakai untuk memperbaiki gejala, sementara penyebabnya tetap di tempat.</p><h3>Yang perlu diperhatikan</h3><ul><li>Ukuran keberhasilan tidak disepakati sebelum program dimulai.</li><li>Data yang sudah dimiliki perusahaan jarang dilihat kembali.</li><li>Pihak yang paling terdampak tidak dilibatkan sejak awal.</li></ul><h2>Cara memperbaikinya</h2><p>Langkah pertama selalu memperjelas apa yang hendak berubah dan bagaimana perubahan itu akan terlihat. Tanpa itu, program apa pun sulit dinilai berhasil atau tidak, dan pembahasannya berhenti pada selera.</p><h2>Apa yang berubah setelah diterapkan</h2><p>Perubahan yang paling cepat terasa biasanya bukan pada angka besar, melainkan pada berkurangnya pekerjaan ulang dan perdebatan berulang. Angka menyusul kemudian, setelah kebiasaan barunya bertahan beberapa bulan.</p><h2>Kesimpulan</h2><p>Tidak ada pendekatan tunggal yang cocok untuk semua organisasi. Namun memulai dari pertanyaan yang tepat hampir selalu lebih murah daripada memperbaiki program yang sudah terlanjur berjalan ke arah yang salah.</p>\",\"en\":\"<p>The best person at a job is not automatically the best leader of the people doing it.</p><h2>The problem we keep seeing</h2><p>Across the companies we work with, this issue shows up in almost the same shape every time: the decision comes first and the reasoning is assembled afterwards. Resources then go into treating symptoms while the cause stays put.</p><h3>What to watch for</h3><ul><li>Success measures are not agreed before the programme starts.</li><li>Data the company already holds is rarely revisited.</li><li>Those most affected are not involved from the outset.</li></ul><h2>How to put it right</h2><p>The first step is always to make clear what should change and how that change will be visible. Without it, no programme can be judged a success, and the discussion stops at taste.</p><h2>What changes once it is applied</h2><p>The fastest-felt change is usually not in the headline numbers but in less rework and fewer repeated arguments. The numbers follow later, once the new habit has held for a few months.</p><h2>Conclusion</h2><p>No single approach suits every organisation. But starting from the right question is almost always cheaper than fixing a programme already running in the wrong direction.</p>\"}','blog/icgg6j5gtyi9l42pal67t9orbvsoq4fnicoqkrg7.webp',NULL,'Surabaya, Jawa Timur','published',0,233,'2026-08-21 02:00:00',NULL,NULL,'2026-09-14 08:15:06','2026-09-15 04:52:04'),(5,5,NULL,'{\"id\":\"Menyusun KPI yang Benar-Benar Dikendalikan Pemegang Jabatan\",\"en\":\"Writing KPIs the Role-Holder Actually Controls\"}','menyusun-kpi-yang-benar-benar-dikendalikan-pemegang-jabatan','{\"id\":\"KPI yang hasilnya ditentukan pihak lain hanya menghasilkan frustrasi, bukan perbaikan kinerja.\",\"en\":\"A KPI whose result is decided by someone else produces frustration, not performance.\"}','{\"id\":\"<p>KPI yang hasilnya ditentukan pihak lain hanya menghasilkan frustrasi, bukan perbaikan kinerja.</p><h2>Masalah yang sering terjadi</h2><p>Dalam pendampingan kami di berbagai perusahaan, persoalan ini hampir selalu muncul dalam bentuk yang sama: keputusan diambil lebih dulu, alasannya disusun belakangan. Akibatnya sumber daya terpakai untuk memperbaiki gejala, sementara penyebabnya tetap di tempat.</p><h3>Yang perlu diperhatikan</h3><ul><li>Ukuran keberhasilan tidak disepakati sebelum program dimulai.</li><li>Data yang sudah dimiliki perusahaan jarang dilihat kembali.</li><li>Pihak yang paling terdampak tidak dilibatkan sejak awal.</li></ul><h2>Cara memperbaikinya</h2><p>Langkah pertama selalu memperjelas apa yang hendak berubah dan bagaimana perubahan itu akan terlihat. Tanpa itu, program apa pun sulit dinilai berhasil atau tidak, dan pembahasannya berhenti pada selera.</p><h2>Apa yang berubah setelah diterapkan</h2><p>Perubahan yang paling cepat terasa biasanya bukan pada angka besar, melainkan pada berkurangnya pekerjaan ulang dan perdebatan berulang. Angka menyusul kemudian, setelah kebiasaan barunya bertahan beberapa bulan.</p><h2>Kesimpulan</h2><p>Tidak ada pendekatan tunggal yang cocok untuk semua organisasi. Namun memulai dari pertanyaan yang tepat hampir selalu lebih murah daripada memperbaiki program yang sudah terlanjur berjalan ke arah yang salah.</p>\",\"en\":\"<p>A KPI whose result is decided by someone else produces frustration, not performance.</p><h2>The problem we keep seeing</h2><p>Across the companies we work with, this issue shows up in almost the same shape every time: the decision comes first and the reasoning is assembled afterwards. Resources then go into treating symptoms while the cause stays put.</p><h3>What to watch for</h3><ul><li>Success measures are not agreed before the programme starts.</li><li>Data the company already holds is rarely revisited.</li><li>Those most affected are not involved from the outset.</li></ul><h2>How to put it right</h2><p>The first step is always to make clear what should change and how that change will be visible. Without it, no programme can be judged a success, and the discussion stops at taste.</p><h2>What changes once it is applied</h2><p>The fastest-felt change is usually not in the headline numbers but in less rework and fewer repeated arguments. The numbers follow later, once the new habit has held for a few months.</p><h2>Conclusion</h2><p>No single approach suits every organisation. But starting from the right question is almost always cheaper than fixing a programme already running in the wrong direction.</p>\"}','blog/lmgix6ktsowezg0y2apggfatpmftph4zzjvdfa96.webp',NULL,'Semarang, Jawa Tengah','published',0,268,'2026-08-14 02:00:00',NULL,NULL,'2026-09-14 08:15:06','2026-09-14 08:15:06'),(6,4,NULL,'{\"id\":\"Wawancara Berbasis Perilaku dan Mengapa Ia Lebih Jujur\",\"en\":\"Behaviour-Based Interviews and Why They Are More Honest\"}','wawancara-berbasis-perilaku-dan-mengapa-ia-lebih-jujur','{\"id\":\"Menanyakan apa yang pernah dilakukan seseorang memberi gambaran jauh lebih akurat daripada menanyakan apa yang akan ia lakukan.\",\"en\":\"Asking what someone has done gives a far more accurate picture than asking what they would do.\"}','{\"id\":\"<p>Menanyakan apa yang pernah dilakukan seseorang memberi gambaran jauh lebih akurat daripada menanyakan apa yang akan ia lakukan.</p><h2>Masalah yang sering terjadi</h2><p>Dalam pendampingan kami di berbagai perusahaan, persoalan ini hampir selalu muncul dalam bentuk yang sama: keputusan diambil lebih dulu, alasannya disusun belakangan. Akibatnya sumber daya terpakai untuk memperbaiki gejala, sementara penyebabnya tetap di tempat.</p><h3>Yang perlu diperhatikan</h3><ul><li>Ukuran keberhasilan tidak disepakati sebelum program dimulai.</li><li>Data yang sudah dimiliki perusahaan jarang dilihat kembali.</li><li>Pihak yang paling terdampak tidak dilibatkan sejak awal.</li></ul><h2>Cara memperbaikinya</h2><p>Langkah pertama selalu memperjelas apa yang hendak berubah dan bagaimana perubahan itu akan terlihat. Tanpa itu, program apa pun sulit dinilai berhasil atau tidak, dan pembahasannya berhenti pada selera.</p><h2>Apa yang berubah setelah diterapkan</h2><p>Perubahan yang paling cepat terasa biasanya bukan pada angka besar, melainkan pada berkurangnya pekerjaan ulang dan perdebatan berulang. Angka menyusul kemudian, setelah kebiasaan barunya bertahan beberapa bulan.</p><h2>Kesimpulan</h2><p>Tidak ada pendekatan tunggal yang cocok untuk semua organisasi. Namun memulai dari pertanyaan yang tepat hampir selalu lebih murah daripada memperbaiki program yang sudah terlanjur berjalan ke arah yang salah.</p>\",\"en\":\"<p>Asking what someone has done gives a far more accurate picture than asking what they would do.</p><h2>The problem we keep seeing</h2><p>Across the companies we work with, this issue shows up in almost the same shape every time: the decision comes first and the reasoning is assembled afterwards. Resources then go into treating symptoms while the cause stays put.</p><h3>What to watch for</h3><ul><li>Success measures are not agreed before the programme starts.</li><li>Data the company already holds is rarely revisited.</li><li>Those most affected are not involved from the outset.</li></ul><h2>How to put it right</h2><p>The first step is always to make clear what should change and how that change will be visible. Without it, no programme can be judged a success, and the discussion stops at taste.</p><h2>What changes once it is applied</h2><p>The fastest-felt change is usually not in the headline numbers but in less rework and fewer repeated arguments. The numbers follow later, once the new habit has held for a few months.</p><h2>Conclusion</h2><p>No single approach suits every organisation. But starting from the right question is almost always cheaper than fixing a programme already running in the wrong direction.</p>\"}','blog/owzota1ethu3axhiy0r38dpxc4exhy3btee5s22e.webp',NULL,'Jakarta Selatan, DKI Jakarta','published',0,306,'2026-08-07 02:00:00',NULL,NULL,'2026-09-14 08:15:06','2026-09-15 03:22:33'),(7,6,NULL,'{\"id\":\"Catatan Nyaris Celaka Adalah Data Paling Berharga\",\"en\":\"Near-Miss Records Are Yo