INSERT INTO `partners` (`id`, `name`, `registration_number`, `logo`, `website_url`, `description`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'Lembaga Sertifikasi Profesi Pasar Modal ','LSSPM-0001','partners/o7csleudwtynlhghgsdtpzn50k6bt2pzthtap3qy.webp','https://lsppm.com/','{\"id\":\"Lembaga yang menetapkan skema dan menerbitkan sertifikat kompetensi kerja nasional.\",\"en\":\"The body that sets schemes and issues national work competency certificates.\"}',1,1,'2026-09-14 08:15:01','2026-09-15 07:16:47'),(3,'Asosiasi Sarjana dan Praktisi Administrasi Perkantoran Indonesia','ASPAPI-204','partners/wydkind68bs1huvqlqpdzwailae07mko0lweukfn.webp','https://aspapi.id/','{\"id\":\"Mitra pelaksanaan uji kompetensi bidang keselamatan dan kesehatan kerja.\",\"en\":\"Partner for competency assessment in occupational safety and health.\"}',3,1,'2026-09-14 08:15:01','2026-09-15 07:18:46'),(4,' LSP MSDM QUALITY INDONESIA.',' LSPMSD-77','partners/q4byc3nteokafnsua6ngreuijlimqf04x5q2aami.webp','https://lspmsdmquality.com/','{\"id\":\"Wadah profesi yang menjadi rujukan standar praktik pengelolaan human capital.\",\"en\":\"A professional association setting reference standards for human capital practice.\"}',4,1,'2026-09-14 08:15:01','2026-09-15 07:20:10'),(16,'Lembaga Sertifikasi Profesi Manajemen Bisnis Pemasaran','LSSPM-0001','partners/evcu1yqqmxadcnpmwul5qp4rxsdjxakeb0q4oosw.webp','https://www.lspmbisnispemasaran.com/',NULL,0,1,'2026-09-15 07:53:32','2026-09-15 07:53:32');
