INSERT INTO `partnership_benefits` (`id`, `title`, `description`, `icon`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'{\"id\":\"Program disusun dari kebutuhan Anda\",\"en\":\"Programmes built from your needs\"}','{\"id\":\"Setiap kemitraan dimulai dari analisis kebutuhan pelatihan di tempat Anda, bukan dari katalog yang sudah jadi. Materi, studi kasus, dan contoh yang dipakai diambil dari pekerjaan peserta sehari-hari.\",\"en\":\"Every partnership starts with a training needs analysis at your site, not from an off-the-shelf catalogue. Material, cases, and examples come from participants\' own daily work.\"}','academic-cap',1,1,'2026-09-14 08:15:56','2026-09-14 08:15:56'),(2,'{\"id\":\"Sertifikasi yang diakui secara nasional\",\"en\":\"Nationally recognised certification\"}','{\"id\":\"Uji kompetensi dijalankan mengikuti skema BNSP, sehingga sertifikat yang diterima karyawan Anda berlaku untuk keperluan audit pelanggan, tender, dan persyaratan regulasi.\",\"en\":\"Assessment follows the BNSP scheme, so the certificates your employees receive hold up for customer audits, tenders, and regulatory requirements.\"}','badge-check',2,1,'2026-09-14 08:15:56','2026-09-14 08:15:56'),(3,'{\"id\":\"Pengajar yang berasal dari industri\",\"en\":\"Instructors who come from industry\"}','{\"id\":\"Pengajar kami adalah praktisi yang pernah menjalankan pekerjaan yang mereka ajarkan. Pertanyaan teknis dari peserta dijawab dari pengalaman, bukan dari salindia.\",\"en\":\"Our instructors are practitioners who have done the work they teach. Technical questions get answered from experience, not from slides.\"}','users',3,1,'2026-09-14 08:15:56','2026-09-14 08:15:56'),(4,'{\"id\":\"Hasil yang bisa Anda ukur\",\"en\":\"Results you can measure\"}','{\"id\":\"Setiap program ditutup dengan laporan berisi nilai sebelum dan sesudah, tingkat kelulusan, serta catatan tindak lanjut per peserta, bukan sekadar daftar hadir.\",\"en\":\"Every programme closes with a report showing before-and-after scores, pass rates, and per-participant follow-up notes, not just an attendance list.\"}','chart-bar',4,1,'2026-09-14 08:15:56','2026-09-14 16:15:27'),(5,'{\"id\":\"Jadwal yang menyesuaikan operasional\",\"en\":\"Scheduling that fits operations\"}','{\"id\":\"Pelatihan dan uji kompetensi dapat digelar di lokasi Anda, termasuk mengikuti pola sif, agar tidak ada lini kerja yang harus berhenti selama program berjalan.\",\"en\":\"Training and assessment can run at your site, including around shift patterns, so no work line has to stop while the programme runs.\"}','calendar',5,1,'2026-09-14 08:15:56','2026-09-14 08:15:56'),(6,'{\"id\":\"Pendampingan setelah program selesai\",\"en\":\"Support after the programme ends\"}','{\"id\":\"Kemitraan tidak berhenti di hari terakhir kelas. Kami mendampingi penerapan di tempat kerja dan meninjau perkembangannya bersama tim Anda secara berkala.\",\"en\":\"The partnership does not end on the last day of class. We support workplace application and review progress with your team at regular intervals.\"}','shield-check',6,1,'2026-09-14 08:15:56','2026-09-14 08:15:56');
/*!40000 ALTER TABLE `partnership_benefits` ENABLE KEYS */;
UNLOCK TABLES;

