INSERT INTO `partnership_packages` (`id`, `tier`, `name`, `slug`, `tagline`, `description`, `features`, `price`, `price_note`, `color`, `is_highlighted`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'blue','{\"id\":\"Blue\",\"en\":\"Blue\"}','blue','{\"id\":\"Langkah awal bagi perusahaan yang baru mulai membangun program pelatihan internal.\",\"en\":\"A first step for companies beginning to build an internal training programme.\"}','{\"id\":\"Paket masuk yang mencakup dua program pelatihan in-house dalam setahun beserta laporan hasilnya. Cocok untuk organisasi dengan kebutuhan pengembangan yang masih terfokus pada satu atau dua unit kerja.\",\"en\":\"An entry package covering two in-house training programmes a year plus outcome reports. Suited to organisations whose development needs still centre on one or two units.\"}','{\"id\":[\"2 program pelatihan in-house per tahun\",\"Maksimal 25 peserta per program\",\"Analisis kebutuhan pelatihan awal\",\"Laporan hasil pelatihan per program\",\"Sertifikat kepesertaan untuk seluruh peserta\"],\"en\":[\"Two in-house training programmes per year\",\"Up to 25 participants per programme\",\"Initial training needs analysis\",\"Outcome report for each programme\",\"Attendance certificates for all participants\"],\"0\":\"2 program pelatihan in-house per tahun\",\"1\":\"Maksimal 25 peserta per program\",\"2\":\"Analisis kebutuhan pelatihan awal\",\"3\":\"Laporan hasil pelatihan per program\",\"4\":\"Sertifikat kepesertaan untuk seluruh peserta\"}',25000000.00,'{\"id\":\"per tahun\",\"en\":\"per year\"}','#1D4ED8',0,1,1,'2026-09-14 08:16:08','2026-09-14 08:16:08'),(2,'silver','{\"id\":\"Silver\",\"en\":\"Silver\"}','silver','{\"id\":\"Untuk perusahaan yang menjalankan pelatihan rutin di beberapa departemen sekaligus.\",\"en\":\"For companies running regular training across several departments.\"}','{\"id\":\"Menambah jumlah program, membuka akses uji kompetensi bersertifikat BNSP, dan menyertakan asesmen kompetensi awal sebagai dasar penyusunan rencana pelatihan tahunan.\",\"en\":\"Adds more programmes, opens access to BNSP-certified assessment, and includes an initial competency assessment to ground the annual training plan.\"}','{\"id\":[\"5 program pelatihan in-house per tahun\",\"Maksimal 30 peserta per program\",\"Asesmen kompetensi awal untuk 50 karyawan\",\"1 batch uji kompetensi BNSP\",\"Penyusunan rencana pelatihan tahunan\",\"Laporan perkembangan kompetensi per semester\"],\"en\":[\"Five in-house training programmes per year\",\"Up to 30 participants per programme\",\"Initial competency assessment for 50 employees\",\"One BNSP assessment batch\",\"Annual training plan development\",\"Half-yearly competency progress reports\"],\"0\":\"5 program pelatihan in-house per tahun\",\"1\":\"Maksimal 30 peserta per program\",\"2\":\"Asesmen kompetensi awal untuk 50 karyawan\",\"3\":\"1 batch uji kompetensi BNSP\",\"4\":\"Penyusunan rencana pelatihan tahunan\",\"5\":\"Laporan perkembangan kompetensi per semester\"}',55000000.00,'{\"id\":\"per tahun\",\"en\":\"per year\"}','#94A3B8',0,2,1,'2026-09-14 08:16:08','2026-09-14 08:16:08'),(3,'gold','{\"id\":\"Gold\",\"en\":\"Gold\"}','gold','{\"id\":\"Pilihan paling banyak diambil: pelatihan, sertifikasi, dan pendampingan dalam satu kerangka.\",\"en\":\"The most-chosen option: training, certification, and advisory in one framework.\"}','{\"id\":\"Mencakup program pelatihan sepanjang tahun, dua batch uji kompetensi, serta pendampingan konsultan untuk menyusun peta kompetensi dan jalur pengembangan karyawan.\",\"en\":\"Covers year-round training, two assessment batches, and consultant support in building a competency map and employee development paths.\"}','{\"id\":[\"12 program pelatihan in-house per tahun\",\"Maksimal 35 peserta per program\",\"Asesmen kompetensi untuk 150 karyawan\",\"2 batch uji kompetensi BNSP\",\"Penyusunan peta kompetensi dan jalur karier\",\"Pendampingan konsultan 4 hari per bulan\",\"Prioritas penjadwalan program\"],\"en\":[\"12 in-house training programmes per year\",\"Up to 35 participants per programme\",\"Competency assessment for 150 employees\",\"Two BNSP assessment batches\",\"Competency map and career path development\",\"Four consultant days per month\",\"Priority programme scheduling\"],\"0\":\"12 program pelatihan in-house per tahun\",\"1\":\"Maksimal 35 peserta per program\",\"2\":\"Asesmen kompetensi untuk 150 karyawan\",\"3\":\"2 batch uji kompetensi BNSP\",\"4\":\"Penyusunan peta kompetensi dan jalur karier\",\"5\":\"Pendampingan konsultan 4 hari per bulan\",\"6\":\"Prioritas penjadwalan program\"}',120000000.00,'{\"id\":\"per tahun\",\"en\":\"per year\"}','#D4A017',1,3,1,'2026-09-14 08:16:08','2026-09-14 08:16:08'),(4,'platinum','{\"id\":\"Platinum\",\"en\":\"Platinum\"}','platinum','{\"id\":\"Kemitraan jangka panjang dengan lingkup yang disusun khusus untuk organisasi besar.\",\"en\":\"A long-term partnership with scope built specifically for large organisations.\"}','{\"id\":\"Lingkup, jumlah program, dan tingkat pendampingan disusun bersama berdasarkan sebaran lokasi dan jumlah karyawan. Ditujukan bagi organisasi multi-cabang yang membutuhkan standar kompetensi seragam.\",\"en\":\"Scope, programme volume, and advisory depth are designed together based on site spread and headcount. Aimed at multi-branch organisations needing uniform competency standards.\"}','{\"id\":[\"Jumlah program pelatihan tanpa batas kuota tahunan\",\"Asesmen kompetensi seluruh karyawan\",\"Uji kompetensi BNSP sesuai kebutuhan\",\"Penyiapan tempat uji kompetensi di lokasi Anda\",\"Pendampingan konsultan penuh waktu\",\"Pelatihan pelatih internal (train the trainer)\",\"Tinjauan kemitraan bersama direksi setiap triwulan\"],\"en\":[\"Unlimited annual training programme quota\",\"Competency assessment for the entire workforce\",\"BNSP assessment as required\",\"On-site assessment venue preparation\",\"Full-time consultant support\",\"Train-the-trainer programme for internal trainers\",\"Quarterly partnership review with the board\"],\"0\":\"Jumlah program pelatihan tanpa batas kuota tahunan\",\"1\":\"Asesmen kompetensi seluruh karyawan\",\"2\":\"Uji kompetensi BNSP sesuai kebutuhan\",\"3\":\"Penyiapan tempat uji kompetensi di lokasi Anda\",\"4\":\"Pendampingan konsultan penuh waktu\",\"5\":\"Pelatihan pelatih internal (train the trainer)\",\"6\":\"Tinjauan kemitraan bersama direksi setiap triwulan\"}',NULL,'{\"id\":\"sesuai kesepakatan\",\"en\":\"by agreement\"}','#0F172A',0,4,1,'2026-09-14 08:16:08','2026-09-14 08:16:08');
/*!40000 ALTER TABLE `partnership_packages` ENABLE KEYS */;
