),(82,17,'banners/wgmjsapvc9eigs6nn3bwchwxl8phxvkqhekdcglp.webp','{\"id\":\"Praktik inspeksi K3 di lokasi proyek\",\"en\":\"Safety inspection practice on the project site\"}',2),(83,17,'banners/x4fmwg385lay6gtt1rlzgfotb0zf5v2debth3v0b.webp','{\"id\":\"Simulasi ujian sertifikasi\",\"en\":\"Certification mock examination\"}',3),(84,18,'portfolio/gallery/gri3ipe7numsel8mgjttysecxuamgybr1ysxhbz8.webp','{\"id\":\"Uji ketelitian kerja tahap kedua\",\"en\":\"Second-stage dexterity testing\"}',1),(85,18,'portfolio/gallery/jta1hfdq4seq6kix9f8rcaq3f0kz07o5dk7xd2gi.webp','{\"id\":\"Pengarahan awal operator terpilih\",\"en\":\"Initial briefing for selected operators\"}',2),(86,19,'agenda/armtr8uj6y220q6bfpwmk7rfv5u7vhafxzfziwdt.webp','{\"id\":\"Praktik langsung sistem klaim digital\",\"en\":\"Hands-on practice with the digital claims system\"}',1),(87,19,'agenda/cypuzanzb1fjmn2ectrz8yc0in0dqkfxe1ffthqz.webp','{\"id\":\"Pendampingan di meja kerja pekan pertama\",\"en\":\"Desk-side support in the first week\"}',2),(88,20,'agenda/upyolltfkeayyqu0wrsvaivqmgp5tqp1vmg7n1ge.webp','{\"id\":\"Lokakarya pengelompokan rumpun jabatan\",\"en\":\"Job family grouping workshop\"}',1),(89,20,'agenda/ve35maiqruxnlv3tvmudjdzd3duj8pu4eudnp8mr.webp','{\"id\":\"Sosialisasi panduan karier kepada karyawan\",\"en\":\"Career guide briefing for employees\"}',2),(90,21,'agenda/yqrimxzhzqe36nkdloqt0ayibmnz7bqxh0hytupf.webp','{\"id\":\"Lokakarya identifikasi risiko wilayah tambang\",\"en\":\"Mining area risk identification workshop\"}',1),(91,21,'services/femt61x5fku1xeo71dcnez3elsbke6pe4hzgltpm.webp','{\"id\":\"Peninjauan pengendalian risiko di lapangan\",\"en\":\"Field review of risk controls\"}',2),(92,22,'services/lxmtmhowf2ahkenbnuli0ptj43npawzmlabjiddq.webp','{\"id\":\"Uji praktik pengelasan posisi vertikal\",\"en\":\"Vertical position welding practical test\"}',1),(93,22,'services/lzcyq8f102jcypd8dz77hrqiryispkqxijxch78r.webp','{\"id\":\"Pemeriksaan mutu hasil las oleh penguji\",\"en\":\"Weld quality inspection by the examiner\"}',2),(94,22,'services/rkovyxkjkjgzy4bqtvf41uxwsmfvaqizutolyix1.webp','{\"id\":\"Pelatihan tambahan bagi peserta gelombang kedua\",\"en\":\"Additional training for the second-wave participants\"}',3),(95,23,'services/v5g2xzqolndsss6vcx1jrajtvusjleaejzglhk07.webp','{\"id\":\"Wawancara kandidat bersama pemegang saham\",\"en\":\"Candidate interview with shareholders\"}',1),(96,23,'services/yn5u0f42arnshv2mfsowkkmatavh14e4038ets3j.webp','{\"id\":\"Sesi penyelarasan kriteria jabatan\",\"en\":\"Role criteria alignment session\"}',2);
