INSERT INTO `portfolios` (`id`, `title`, `slug`, `client_name`, `location`, `service_category_id`, `short_description`, `content`, `cover_image`, `project_date`, `is_featured`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'{\"id\":\"Transformasi Human Capital Nasional\",\"en\":\"National Human Capital Transformation\"}','transformasi-human-capital-nasional','PT Nusantara Jaya','Jakarta Selatan, DKI Jakarta',2,'{\"id\":\"Merancang ulang strategi dan struktur SDM untuk 1.200+ karyawan yang tersebar di 12 cabang.\",\"en\":\"Redesigning HR strategy and structure for 1,200+ employees across 12 branches.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Pertumbuhan cepat membuat struktur organisasi di 12 cabang tidak lagi seragam. Jenjang jabatan berbeda-beda antarwilayah, sehingga rotasi karyawan sulit dilakukan dan biaya gaji tidak dapat dibandingkan antarcabang.</p><h2>Pendekatan Kami</h2><p>Kami memulai dari pemetaan seluruh jabatan yang ada, lalu menyusun satu kerangka jenjang tunggal yang berlaku nasional sebelum memindahkan karyawan ke dalamnya secara bertahap.</p><h3>Lingkup Pengerjaan</h3><ul><li>Analisis jabatan pada 168 posisi unik di seluruh cabang.</li><li>Penyusunan kerangka jenjang jabatan tunggal 9 tingkat.</li><li>Pendampingan tim HR pusat selama masa transisi enam bulan.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Struktur jabatan seragam di 12 cabang dalam waktu enam bulan.</li><li>Waktu proses rotasi antarcabang turun dari 6 pekan menjadi 2 pekan.</li><li>Biaya gaji per jenjang dapat dibandingkan antarwilayah untuk pertama kalinya.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Nusantara Jaya.</p>\",\"en\":\"<h2>Background</h2><p>Rapid growth left the organisational structure inconsistent across 12 branches. Job levels differed by region, making staff rotation difficult and payroll costs impossible to compare between branches.</p><h2>Our Approach</h2><p>We began by mapping every existing role, then built a single national job-level framework before migrating employees into it in stages.</p><h3>Scope of Work</h3><ul><li>Job analysis across 168 unique positions in all branches.</li><li>Design of a single nine-tier job-level framework.</li><li>Coaching the central HR team through a six-month transition.</li></ul><h2>Results Achieved</h2><ul><li>Uniform job structure across 12 branches within six months.</li><li>Inter-branch rotation time cut from six weeks to two.</li><li>Payroll cost per level became comparable across regions for the first time.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Nusantara Jaya.</p>\"}','portfolio/kjici5m3lzofm4o00ykrcvewzetvvztyk2reoh8e.webp','2025-02-15',1,1,1,'2026-09-14 07:42:57','2026-09-14 08:14:06'),(2,'{\"id\":\"Program Pelatihan Kepemimpinan Lini\",\"en\":\"Line Leadership Development Program\"}','program-pelatihan-kepemimpinan','Bank Sinar Mas','Jakarta Pusat, DKI Jakarta',4,'{\"id\":\"Membangun 80 pemimpin lini melalui pelatihan berbasis studi kasus selama enam bulan.\",\"en\":\"Building 80 line leaders through six months of case-study based training.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Banyak supervisor diangkat karena keahlian teknis, bukan karena kesiapan memimpin. Akibatnya keluhan tim meningkat dan tingkat pengunduran diri di lapisan staf muda ikut naik.</p><h2>Pendekatan Kami</h2><p>Materi disusun dari kasus nyata yang diambil dari catatan internal bank, bukan contoh generik, sehingga setiap peserta melatih keputusan yang benar-benar akan mereka hadapi.</p><h3>Lingkup Pengerjaan</h3><ul><li>Delapan modul kelas dengan total 96 jam tatap muka.</li><li>Proyek perbaikan nyata di unit masing-masing peserta.</li><li>Umpan balik 360 derajat sebelum dan sesudah program.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>80 supervisor menyelesaikan program dengan tingkat kehadiran 94%.</li><li>Skor umpan balik bawahan naik rata-rata 1,2 poin dari skala 5.</li><li>31 proyek perbaikan unit dijalankan sampai selesai.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal Bank Sinar Mas.</p>\",\"en\":\"<h2>Background</h2><p>Many supervisors were promoted for technical skill rather than leadership readiness. Team complaints rose and attrition among junior staff climbed with them.</p><h2>Our Approach</h2><p>The material was built from real cases drawn from the bank\'s own records rather than generic examples, so every participant practised decisions they would actually face.</p><h3>Scope of Work</h3><ul><li>Eight classroom modules totalling 96 contact hours.</li><li>A real improvement project inside each participant\'s own unit.</li><li>360-degree feedback before and after the programme.</li></ul><h2>Results Achieved</h2><ul><li>80 supervisors completed the programme with 94% attendance.</li><li>Subordinate feedback scores rose an average of 1.2 points out of 5.</li><li>31 unit improvement projects were carried through to completion.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at Bank Sinar Mas.</p>\"}','services/femt61x5fku1xeo71dcnez3elsbke6pe4hzgltpm.webp','2025-04-08',1,2,1,'2026-09-14 07:42:57','2026-09-14 08:14:06'),(3,'{\"id\":\"Rekrutmen Eksekutif C-Level\",\"en\":\"C-Level Executive Search\"}','rekrutmen-eksekutif-c-level','Global Energi Group','Jakarta Selatan, DKI Jakarta',3,'{\"id\":\"Penempatan CFO dan COO melalui proses headhunter yang selektif dan terukur.\",\"en\":\"Placing a CFO and COO through a selective, measured executive-search process.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Dua posisi kunci kosong bersamaan menjelang penutupan tahun buku. Pencarian sebelumnya berjalan delapan bulan tanpa hasil karena kandidat yang masuk tidak memiliki pengalaman sektor energi.</p><h2>Pendekatan Kami</h2><p>Kami menyusun daftar panjang dari pemetaan langsung perusahaan sejenis, bukan dari papan lowongan, lalu melakukan pendekatan tertutup agar proses tidak terbaca pasar.</p><h3>Lingkup Pengerjaan</h3><ul><li>Pemetaan 47 kandidat dari 19 perusahaan sektor energi.</li><li>Asesmen kompetensi dan wawancara berbasis perilaku.</li><li>Penelusuran rekam jejak dan pendampingan negosiasi.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Kedua posisi terisi dalam 11 pekan sejak penugasan.</li><li>Lima kandidat final diajukan, seluruhnya lolos tahap direksi.</li><li>Kedua eksekutif masih menjabat setelah masa garansi 12 bulan.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal Global Energi Group.</p>\",\"en\":\"<h2>Background</h2><p>Two key posts fell vacant at once as the financial year closed. A previous search had run eight months without result because the candidates lacked energy-sector experience.</p><h2>Our Approach</h2><p>We built the long list by directly mapping comparable companies rather than posting jobs, then approached candidates confidentially so the process stayed off the market\'s radar.</p><h3>Scope of Work</h3><ul><li>Mapping 47 candidates from 19 energy-sector companies.</li><li>Competency assessment and behaviour-based interviews.</li><li>Reference checking and offer-negotiation support.</li></ul><h2>Results Achieved</h2><ul><li>Both roles filled within 11 weeks of engagement.</li><li>Five finalists submitted, all cleared the board stage.</li><li>Both executives remained in post beyond the 12-month guarantee period.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at Global Energi Group.</p>\"}','services/gzefafk6sptj1kqryp3d9evmmvpd1raeseiqyfkv.webp','2024-11-20',1,3,1,'2026-09-14 07:42:57','2026-09-14 08:14:06'),(7,'{\"id\":\"Sertifikasi Kompetensi Operator Produksi\",\"en\":\"Production Operator Competency Certification\"}','sertifikasi-kompetensi-operator-produksi','PT Baja Perkasa','Cilegon, Banten',5,'{\"id\":\"Sertifikasi BNSP bagi 240 operator produksi dalam empat gelombang uji kompetensi.\",\"en\":\"BNSP certification for 240 production operators across four assessment waves.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Audit pelanggan mensyaratkan seluruh operator lini bersertifikat dalam satu tahun, sementara produksi tidak boleh berhenti. Jadwal uji harus menyesuaikan pola tiga sif.</p><h2>Pendekatan Kami</h2><p>Uji kompetensi digelar di tempat kerja pada jam sif masing-masing peserta, sehingga tidak ada lini yang berhenti dan peserta diuji pada mesin yang benar-benar mereka operasikan.</p><h3>Lingkup Pengerjaan</h3><ul><li>Pelatihan penyegaran 24 jam sebelum uji kompetensi.</li><li>Uji kompetensi BNSP di tempat kerja untuk 240 operator.</li><li>Penyusunan arsip bukti kompetensi untuk keperluan audit.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>228 dari 240 operator dinyatakan kompeten pada percobaan pertama.</li><li>Nol jam produksi hilang selama seluruh rangkaian uji.</li><li>Temuan audit pelanggan mengenai kompetensi operator ditutup.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Baja Perkasa.</p>\",\"en\":\"<h2>Background</h2><p>A customer audit required every line operator certified within a year, yet production could not stop. The assessment schedule had to fit a three-shift pattern.</p><h2>Our Approach</h2><p>Assessments ran on site during each participant\'s own shift, so no line stopped and operators were tested on the machines they actually run.</p><h3>Scope of Work</h3><ul><li>24 hours of refresher training ahead of assessment.</li><li>On-site BNSP assessment for 240 operators.</li><li>Building a competency evidence archive for audit purposes.</li></ul><h2>Results Achieved</h2><ul><li>228 of 240 operators judged competent on the first attempt.</li><li>Zero production hours lost across the whole assessment series.</li><li>The customer audit finding on operator competency was closed.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Baja Perkasa.</p>\"}','services/lxmtmhowf2ahkenbnuli0ptj43npawzmlabjiddq.webp','2025-01-10',1,4,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(8,'{\"id\":\"Restrukturisasi Organisasi Manufaktur\",\"en\":\"Manufacturing Organisation Restructuring\"}','restrukturisasi-organisasi-manufaktur','PT Cipta Mandiri Manufaktur','Cikarang, Jawa Barat',1,'{\"id\":\"Merampingkan tujuh lapis struktur menjadi lima tanpa pemutusan hubungan kerja.\",\"en\":\"Flattening seven management layers to five without any redundancies.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Keputusan sederhana perlu melewati tujuh lapis persetujuan. Waktu tanggap terhadap keluhan pelanggan rata-rata sembilan hari kerja, jauh di atas janji layanan perusahaan.</p><h2>Pendekatan Kami</h2><p>Alih-alih memangkas orang, kami memangkas titik persetujuan: setiap lapis yang tidak menambah keputusan dihapus, dan wewenangnya diturunkan ke jenjang di bawahnya.</p><h3>Lingkup Pengerjaan</h3><ul><li>Pemetaan alur persetujuan pada 24 proses inti.</li><li>Perancangan struktur baru lima lapis beserta matriks wewenang.</li><li>Penempatan ulang 38 karyawan ke peran yang setara.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Waktu tanggap keluhan pelanggan turun dari 9 hari menjadi 3 hari.</li><li>Tidak ada pemutusan hubungan kerja sepanjang proses.</li><li>Biaya overhead manajemen turun 14% dalam setahun.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Cipta Mandiri Manufaktur.</p>\",\"en\":\"<h2>Background</h2><p>A simple decision had to pass seven approval layers. Average response time to customer complaints was nine working days, far beyond the company\'s service promise.</p><h2>Our Approach</h2><p>Rather than cutting people, we cut approval points: every layer that added no decision was removed and its authority pushed down one level.</p><h3>Scope of Work</h3><ul><li>Mapping approval flows across 24 core processes.</li><li>Designing a new five-layer structure with an authority matrix.</li><li>Redeploying 38 employees into equivalent roles.</li></ul><h2>Results Achieved</h2><ul><li>Complaint response time fell from nine days to three.</li><li>No redundancies throughout the process.</li><li>Management overhead dropped 14% within a year.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Cipta Mandiri Manufaktur.</p>\"}','services/lzcyq8f102jcypd8dz77hrqiryispkqxijxch78r.webp','2024-09-05',0,5,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(9,'{\"id\":\"Asesmen Kompetensi Supervisor\",\"en\":\"Supervisor Competency Assessment\"}','asesmen-kompetensi-supervisor','PT Tirta Anugerah','Serang, Banten',2,'{\"id\":\"Assessment center bagi 95 supervisor sebagai dasar keputusan promosi dan pengembangan.\",\"en\":\"An assessment centre for 95 supervisors informing promotion and development decisions.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Keputusan promosi selama ini bergantung pada penilaian atasan langsung, yang berbeda standar antardepartemen. Beberapa promosi terbukti keliru dan sulit dikoreksi.</p><h2>Pendekatan Kami</h2><p>Kami menjalankan assessment center dengan simulasi yang sama bagi semua peserta, dinilai oleh asesor bersertifikat dari luar departemen agar hasilnya setara dan dapat dibandingkan.</p><h3>Lingkup Pengerjaan</h3><ul><li>Penyusunan kamus kompetensi untuk jenjang supervisor.</li><li>Assessment center dua hari untuk 95 peserta.</li><li>Laporan individual berisi rencana pengembangan.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>95 laporan individual diserahkan lengkap dengan rencana pengembangan.</li><li>22 supervisor teridentifikasi siap naik jenjang dalam setahun.</li><li>Standar penilaian promosi menjadi seragam di seluruh departemen.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Tirta Anugerah.</p>\",\"en\":\"<h2>Background</h2><p>Promotion decisions had rested on line-manager judgement, which varied in standard between departments. Several promotions proved wrong and were hard to reverse.</p><h2>Our Approach</h2><p>We ran an assessment centre using identical simulations for every participant, scored by certified assessors from outside the department so results were comparable.</p><h3>Scope of Work</h3><ul><li>Building a competency dictionary for the supervisor level.</li><li>A two-day assessment centre for 95 participants.</li><li>Individual reports containing development plans.</li></ul><h2>Results Achieved</h2><ul><li>95 individual reports delivered with development plans.</li><li>22 supervisors identified as ready for promotion within a year.</li><li>Promotion assessment standards became uniform across departments.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Tirta Anugerah.</p>\"}','services/rkovyxkjkjgzy4bqtvf41uxwsmfvaqizutolyix1.webp','2025-03-12',0,6,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(10,'{\"id\":\"Pelatihan K3 Industri Migas\",\"en\":\"Oil & Gas Occupational Safety Training\"}','pelatihan-k3-industri-migas','PT Lintas Samudra Energi','Balikpapan, Kalimantan Timur',4,'{\"id\":\"Pelatihan keselamatan kerja bagi 160 pekerja lapangan di dua lokasi operasi.\",\"en\":\"Safety training for 160 field workers across two operating sites.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Angka nyaris celaka meningkat pada pekerja kontrak yang berganti setiap enam bulan. Pelatihan induksi yang ada terlalu umum dan tidak menyentuh bahaya spesifik di lokasi.</p><h2>Pendekatan Kami</h2><p>Materi disusun ulang dari catatan insiden dua tahun terakhir di lokasi itu sendiri, sehingga bahaya yang dibahas adalah bahaya yang benar-benar pernah terjadi di sana.</p><h3>Lingkup Pengerjaan</h3><ul><li>Analisis 214 catatan insiden dan nyaris celaka.</li><li>Pelatihan 32 jam di dua lokasi operasi.</li><li>Latihan tanggap darurat dengan skenario lokasi nyata.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Laporan nyaris celaka turun 41% pada semester berikutnya.</li><li>160 pekerja menyelesaikan pelatihan dan lulus uji akhir.</li><li>Materi induksi baru dipakai permanen untuk pekerja masuk.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Lintas Samudra Energi.</p>\",\"en\":\"<h2>Background</h2><p>Near-miss counts rose among contract workers who rotated every six months. The existing induction was too generic to address site-specific hazards.</p><h2>Our Approach</h2><p>Material was rebuilt from two years of incident records at the sites themselves, so the hazards discussed were ones that had genuinely occurred there.</p><h3>Scope of Work</h3><ul><li>Analysis of 214 incident and near-miss records.</li><li>32 hours of training at two operating sites.</li><li>Emergency drills using real site scenarios.</li></ul><h2>Results Achieved</h2><ul><li>Near-miss reports fell 41% the following half-year.</li><li>160 workers completed training and passed the final test.</li><li>The new induction material became permanent for incoming workers.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Lintas Samudra Energi.</p>\"}','services/v5g2xzqolndsss6vcx1jrajtvusjleaejzglhk07.webp','2024-12-02',0,7,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(11,'{\"id\":\"Talent Mapping Perbankan Daerah\",\"en\":\"Regional Banking Talent Mapping\"}','talent-mapping-perbankan-daerah','Bank Pembangunan Daerah Jabar','Bandung, Jawa Barat',2,'{\"id\":\"Memetakan kesiapan 310 karyawan untuk mengisi 45 posisi kunci dalam tiga tahun.\",\"en\":\"Mapping 310 employees\' readiness to fill 45 key roles over three years.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Sepertiga pemegang jabatan kunci akan pensiun dalam tiga tahun, sementara bank belum punya gambaran siapa yang siap menggantikan dan siapa yang masih perlu disiapkan.</p><h2>Pendekatan Kami</h2><p>Setiap karyawan dinilai pada dua sumbu, yaitu kinerja saat ini dan potensi jangka panjang, lalu ditempatkan pada kisi sembilan kotak yang menjadi dasar keputusan pengembangan.</p><h3>Lingkup Pengerjaan</h3><ul><li>Penilaian potensi dan kinerja atas 310 karyawan.</li><li>Penyusunan peta suksesi untuk 45 posisi kunci.</li><li>Rancangan program pengembangan bagi 60 kandidat suksesor.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>45 posisi kunci memiliki minimal dua kandidat pengganti.</li><li>60 karyawan masuk program pengembangan terarah.</li><li>Risiko kekosongan jabatan kunci terpetakan sampai 2028.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal Bank Pembangunan Daerah Jabar.</p>\",\"en\":\"<h2>Background</h2><p>A third of key post-holders would retire within three years, yet the bank had no picture of who was ready to step up and who still needed preparing.</p><h2>Our Approach</h2><p>Every employee was rated on two axes, current performance and long-term potential, then placed on a nine-box grid that guided development decisions.</p><h3>Scope of Work</h3><ul><li>Potential and performance review of 310 employees.</li><li>Building a succession map for 45 key roles.</li><li>Designing a development programme for 60 successor candidates.</li></ul><h2>Results Achieved</h2><ul><li>All 45 key roles gained at least two successor candidates.</li><li>60 employees entered a targeted development programme.</li><li>Key-role vacancy risk mapped through to 2028.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at Bank Pembangunan Daerah Jabar.</p>\"}','services/yn5u0f42arnshv2mfsowkkmatavh14e4038ets3j.webp','2025-05-20',0,8,1,'2026-09-14 08:14:06','2026-09-14 16:15:35'),(12,'{\"id\":\"Sertifikasi BNSP Teknisi Listrik\",\"en\":\"BNSP Electrical Technician Certification\"}','sertifikasi-bnsp-teknisi-listrik','PT Sumber Daya Elektrik','Surabaya, Jawa Timur',5,'{\"id\":\"Sertifikasi 85 teknisi listrik tegangan menengah beserta penyiapan tempat uji kompetensi.\",\"en\":\"Certifying 85 medium-voltage electrical technicians and preparing an assessment venue.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Regulasi mewajibkan teknisi tegangan menengah bersertifikat, namun tempat uji terdekat berada di luar kota dan mengharuskan teknisi meninggalkan pekerjaan berhari-hari.</p><h2>Pendekatan Kami</h2><p>Kami menyiapkan tempat uji kompetensi di dalam lokasi klien sendiri, termasuk verifikasi peralatan dan pelatihan calon asesor internal, agar biaya uji berikutnya jauh lebih murah.</p><h3>Lingkup Pengerjaan</h3><ul><li>Verifikasi kelayakan tempat uji kompetensi di lokasi klien.</li><li>Pelatihan penyegaran dan uji kompetensi 85 teknisi.</li><li>Penyiapan tiga calon asesor internal.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>85 teknisi bersertifikat tanpa perjalanan ke luar kota.</li><li>Tempat uji kompetensi internal resmi terverifikasi.</li><li>Biaya sertifikasi per orang turun 38% untuk angkatan berikutnya.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Sumber Daya Elektrik.</p>\",\"en\":\"<h2>Background</h2><p>Regulation required medium-voltage technicians to hold certificates, but the nearest assessment venue was out of town and meant days away from work.</p><h2>Our Approach</h2><p>We set up an assessment venue inside the client\'s own site, including equipment verification and internal assessor training, so future assessments would cost far less.</p><h3>Scope of Work</h3><ul><li>Verifying the on-site assessment venue for eligibility.</li><li>Refresher training and assessment for 85 technicians.</li><li>Preparing three internal assessor candidates.</li></ul><h2>Results Achieved</h2><ul><li>85 technicians certified without any out-of-town travel.</li><li>The internal assessment venue was formally verified.</li><li>Per-person certification cost fell 38% for the next cohort.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Sumber Daya Elektrik.</p>\"}','banners/5io6kmyhdxhimmubqapiq8ss85uuho5o1uxszyuu.webp','2025-02-28',0,9,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(13,'{\"id\":\"Pencarian Manajer Pabrik Agroindustri\",\"en\":\"Agro-Industry Plant Manager Search\"}','headhunter-manajer-pabrik-agro','PT Agro Lestari Nusantara','Medan, Sumatera Utara',3,'{\"id\":\"Mengisi tiga posisi manajer pabrik di lokasi terpencil yang sulit menarik kandidat.\",\"en\":\"Filling three plant manager roles at remote sites that struggled to attract candidates.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Tiga pabrik berada jauh dari pusat kota dan kandidat berpengalaman umumnya menolak relokasi. Dua lowongan sudah terbuka lebih dari setahun.</p><h2>Pendekatan Kami</h2><p>Kami memusatkan pencarian pada kandidat yang berasal dari wilayah itu dan ingin kembali, lalu membantu klien menyusun paket relokasi keluarga yang menjawab keberatan utama mereka.</p><h3>Lingkup Pengerjaan</h3><ul><li>Pemetaan kandidat berlatar daerah asal di tiga provinsi.</li><li>Kajian pembanding paket remunerasi dan relokasi.</li><li>Wawancara berbasis perilaku dan penelusuran rekam jejak.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Tiga posisi terisi dalam 14 pekan setelah setahun kosong.</li><li>Seluruh kandidat terpilih menerima penempatan tanpa negosiasi ulang.</li><li>Paket relokasi baru dipakai ulang untuk rekrutmen berikutnya.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Agro Lestari Nusantara.</p>\",\"en\":\"<h2>Background</h2><p>Three plants sat far from any city and experienced candidates generally refused relocation. Two vacancies had been open for over a year.</p><h2>Our Approach</h2><p>We focused the search on candidates originally from the region who wanted to return, then helped the client build a family relocation package answering their main objection.</p><h3>Scope of Work</h3><ul><li>Mapping regionally-rooted candidates across three provinces.</li><li>Benchmarking remuneration and relocation packages.</li><li>Behaviour-based interviews and reference checks.</li></ul><h2>Results Achieved</h2><ul><li>Three roles filled in 14 weeks after a year of vacancy.</li><li>Every selected candidate accepted placement without renegotiation.</li><li>The new relocation package was reused for later hiring.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Agro Lestari Nusantara.</p>\"}','banners/68axjqvezdml8wxw7bplgd8iojmpdtinajy6pcao.webp','2024-10-14',0,10,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(14,'{\"id\":\"Penyusunan KPI dan Sistem Remunerasi\",\"en\":\"KPI and Remuneration System Design\"}','penyusunan-kpi-dan-sistem-remunerasi','PT Karya Bangun Sejahtera','Semarang, Jawa Tengah',1,'{\"id\":\"Menghubungkan sasaran perusahaan ke KPI individu dan struktur gaji yang transparan.\",\"en\":\"Linking company targets to individual KPIs and a transparent pay structure.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Kenaikan gaji diberikan merata setiap tahun tanpa kaitan dengan pencapaian. Karyawan berkinerja tinggi merasa tidak dihargai dan beberapa di antaranya mengundurkan diri.</p><h2>Pendekatan Kami</h2><p>Sasaran perusahaan diturunkan berjenjang sampai ke KPI individu, lalu struktur gaji disusun ulang dengan rentang yang jelas sehingga setiap orang tahu posisinya dan apa yang menaikkannya.</p><h3>Lingkup Pengerjaan</h3><ul><li>Penurunan sasaran perusahaan ke 14 departemen.</li><li>Penyusunan KPI individu untuk 9 jenjang jabatan.</li><li>Kajian pembanding gaji terhadap pasar industri sejenis.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Rentang gaji tiap jenjang terdokumentasi dan dibuka ke karyawan.</li><li>Pengunduran diri sukarela turun dari 18% menjadi 11% setahun.</li><li>Anggaran kenaikan gaji dialihkan ke pencapaian, bukan masa kerja.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Karya Bangun Sejahtera.</p>\",\"en\":\"<h2>Background</h2><p>Pay rises were granted evenly each year with no link to achievement. High performers felt unrecognised and several resigned.</p><h2>Our Approach</h2><p>Company targets were cascaded down to individual KPIs, then the pay structure was rebuilt with clear ranges so everyone knew where they stood and what would move them.</p><h3>Scope of Work</h3><ul><li>Cascading company targets to 14 departments.</li><li>Designing individual KPIs for nine job levels.</li><li>Salary benchmarking against comparable industry data.</li></ul><h2>Results Achieved</h2><ul><li>Pay ranges per level documented and disclosed to employees.</li><li>Voluntary attrition fell from 18% to 11% a year.</li><li>The pay-rise budget shifted to achievement rather than tenure.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Karya Bangun Sejahtera.</p>\"}','banners/6b62xmd0k2mw3lswgkw7aesczpphojwtep7vkfrs.webp','2025-06-18',0,11,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(15,'{\"id\":\"Pelatihan Layanan Pelanggan Ritel\",\"en\":\"Retail Customer Service Training\"}','pelatihan-layanan-pelanggan-ritel','PT Ritel Maju Bersama','Tangerang, Banten',4,'{\"id\":\"Menyeragamkan mutu layanan 420 staf toko di 35 gerai melalui satu standar layanan.\",\"en\":\"Standardising service quality for 420 store staff across 35 outlets.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Nilai kepuasan pelanggan berbeda jauh antargerai. Gerai terbaik dan terburuk terpaut 34 poin, padahal produk dan harga yang dijual sama persis.</p><h2>Pendekatan Kami</h2><p>Kami mengamati langsung praktik di gerai berkinerja terbaik, mengangkatnya menjadi standar tertulis, lalu melatihkannya ke seluruh gerai melalui pelatih internal.</p><h3>Lingkup Pengerjaan</h3><ul><li>Observasi lapangan di 8 gerai berkinerja tertinggi dan terendah.</li><li>Penyusunan standar layanan dan naskah penanganan keluhan.</li><li>Pelatihan 28 pelatih internal untuk penyebaran mandiri.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Selisih nilai kepuasan antargerai menyempit dari 34 ke 9 poin.</li><li>420 staf toko menyelesaikan pelatihan dalam 11 pekan.</li><li>Penyegaran tahunan dijalankan mandiri oleh pelatih internal.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Ritel Maju Bersama.</p>\",\"en\":\"<h2>Background</h2><p>Customer satisfaction varied sharply between outlets. The best and worst were 34 points apart despite identical products and pricing.</p><h2>Our Approach</h2><p>We observed practice directly in the best-performing outlets, turned it into a written standard, then trained it across all outlets through internal trainers.</p><h3>Scope of Work</h3><ul><li>Field observation in the eight highest and lowest performing outlets.</li><li>Writing service standards and complaint-handling scripts.</li><li>Training 28 internal trainers for self-sustained rollout.</li></ul><h2>Results Achieved</h2><ul><li>The outlet satisfaction gap narrowed from 34 points to nine.</li><li>420 store staff completed training within 11 weeks.</li><li>Annual refreshers now run independently by internal trainers.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Ritel Maju Bersama.</p>\"}','banners/fiaagkurioh1qjmqsbvquepqi2y2qhbbbkp9z8uq.webp','2025-07-09',0,12,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(16,'{\"id\":\"Audit Struktur Organisasi Rumah Sakit\",\"en\":\"Hospital Organisational Structure Audit\"}','audit-struktur-organisasi-rumah-sakit','RS Harapan Sehat','Yogyakarta, DI Yogyakarta',1,'{\"id\":\"Menata ulang pembagian tugas 18 unit layanan menjelang akreditasi rumah sakit.\",\"en\":\"Reorganising duty allocation across 18 service units ahead of hospital accreditation.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Uraian tugas banyak jabatan sudah tidak sesuai praktik sehari-hari, dan sebagian tanggung jawab tumpang tindih antarunit. Ini menjadi temuan berulang pada penilaian akreditasi sebelumnya.</p><h2>Pendekatan Kami</h2><p>Kami menelusuri apa yang benar-benar dikerjakan tiap unit lebih dulu, baru menulis ulang uraian tugas dari kenyataan itu, bukan dari struktur di atas kertas.</p><h3>Lingkup Pengerjaan</h3><ul><li>Wawancara dan observasi kerja pada 18 unit layanan.</li><li>Penulisan ulang 112 uraian tugas jabatan.</li><li>Penyusunan matriks tanggung jawab antarunit.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>112 uraian tugas selesai dan disahkan direksi.</li><li>Tumpang tindih tanggung jawab antarunit terurai seluruhnya.</li><li>Temuan akreditasi mengenai uraian tugas tidak terulang.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal RS Harapan Sehat.</p>\",\"en\":\"<h2>Background</h2><p>Many job descriptions no longer matched daily practice and some responsibilities overlapped between units, a repeat finding in the previous accreditation review.</p><h2>Our Approach</h2><p>We traced what each unit actually did first, then rewrote job descriptions from that reality rather than from the structure on paper.</p><h3>Scope of Work</h3><ul><li>Interviews and work observation across 18 service units.</li><li>Rewriting 112 job descriptions.</li><li>Building an inter-unit responsibility matrix.</li></ul><h2>Results Achieved</h2><ul><li>112 job descriptions completed and ratified by the board.</li><li>All inter-unit responsibility overlaps were resolved.</li><li>The accreditation finding on job descriptions did not recur.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at RS Harapan Sehat.</p>\"}','banners/gfg9vigap3sf01x6yazyfla1oyzorrp5nfwfd9si.webp','2024-08-22',0,13,1,'2026-09-14 08:14:06','2026-09-14 16:15:35'),(17,'{\"id\":\"Sertifikasi Ahli K3 Umum\",\"en\":\"General Occupational Safety Expert Certification\"}','sertifikasi-ahli-k3-umum','PT Konstruksi Bumi Persada','Makassar, Sulawesi Selatan',5,'{\"id\":\"Menyiapkan 40 pengawas proyek memperoleh sertifikat Ahli K3 Umum.\",\"en\":\"Preparing 40 project supervisors to obtain General Safety Expert certification.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Setiap proyek baru mensyaratkan sejumlah Ahli K3 bersertifikat, sementara perusahaan hanya punya empat orang. Keterbatasan ini mulai menutup peluang ikut tender besar.</p><h2>Pendekatan Kami</h2><p>Pelatihan dijalankan dalam pola dua pekan penuh agar peserta dari berbagai proyek bisa dikumpulkan sekaligus, dengan pendalaman soal berbasis kasus proyek konstruksi mereka sendiri.</p><h3>Lingkup Pengerjaan</h3><ul><li>Pelatihan 120 jam sesuai kurikulum Ahli K3 Umum.</li><li>Pendalaman soal dan simulasi ujian sertifikasi.</li><li>Pendampingan penyusunan laporan praktik kerja lapangan.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>37 dari 40 peserta lulus sertifikasi pada percobaan pertama.</li><li>Jumlah Ahli K3 bersertifikat naik dari 4 menjadi 41 orang.</li><li>Perusahaan memenuhi syarat K3 untuk tender proyek besar.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Konstruksi Bumi Persada.</p>\",\"en\":\"<h2>Background</h2><p>Every new project required a quota of certified safety experts while the company had only four. The shortfall was starting to close off large tenders.</p><h2>Our Approach</h2><p>Training ran as two full weeks so participants from different projects could be gathered at once, with exam practice built on their own construction cases.</p><h3>Scope of Work</h3><ul><li>120 hours of training following the safety expert curriculum.</li><li>Exam drilling and certification mock tests.</li><li>Support in preparing field practice reports.</li></ul><h2>Results Achieved</h2><ul><li>37 of 40 participants passed certification at the first attempt.</li><li>Certified safety experts rose from four to 41.</li><li>The company met safety requirements for large project tenders.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Konstruksi Bumi Persada.</p>\"}','banners/hyaw5exeksaq5myly5i27ig4w0yabxib57icdmgp.webp','2025-04-25',0,14,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(18,'{\"id\":\"Rekrutmen Massal Operator Produksi\",\"en\":\"Mass Production Operator Recruitment\"}','rekrutmen-massal-operator-produksi','PT Tekstil Indah Permai','Karawang, Jawa Barat',3,'{\"id\":\"Menyaring 2.400 pelamar menjadi 300 operator terpilih untuk pembukaan lini baru.\",\"en\":\"Screening 2,400 applicants down to 300 selected operators for a new production line.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Lini produksi baru harus berjalan dalam sepuluh pekan dan membutuhkan 300 operator sekaligus. Proses seleksi manual perusahaan tidak sanggup menangani volume sebesar itu.</p><h2>Pendekatan Kami</h2><p>Seleksi dibagi menjadi tahap penyaringan cepat berbasis syarat mutlak lalu uji ketelitian praktis, sehingga waktu wawancara hanya dipakai untuk kandidat yang sudah lolos dua saringan.</p><h3>Lingkup Pengerjaan</h3><ul><li>Penyaringan administratif 2.400 pelamar.</li><li>Uji ketelitian dan ketahanan kerja untuk 780 kandidat.</li><li>Wawancara akhir dan pemeriksaan kesehatan 340 kandidat.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>300 operator terpilih dan mulai bekerja tepat waktu.</li><li>Seluruh proses selesai dalam 9 pekan dari 10 pekan tersedia.</li><li>Tingkat bertahan kerja 92% setelah tiga bulan pertama.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Tekstil Indah Permai.</p>\",\"en\":\"<h2>Background</h2><p>A new line had to start within ten weeks and needed 300 operators at once. The company\'s manual selection process could not handle that volume.</p><h2>Our Approach</h2><p>Selection was split into a fast knock-out screen on hard requirements then a practical dexterity test, so interview time was spent only on candidates past two filters.</p><h3>Scope of Work</h3><ul><li>Administrative screening of 2,400 applicants.</li><li>Dexterity and work-endurance testing for 780 candidates.</li><li>Final interviews and medical checks for 340 candidates.</li></ul><h2>Results Achieved</h2><ul><li>300 operators selected and started on schedule.</li><li>The whole process finished in nine of the ten weeks available.</li><li>92% retention after the first three months.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Tekstil Indah Permai.</p>\"}','banners/oqgffif0kblarkcq1q4akl8c0qbz6ecy3xc4vhdi.webp','2025-03-30',0,15,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(19,'{\"id\":\"Pelatihan Pola Pikir Digital Asuransi\",\"en\":\"Insurance Digital Mindset Training\"}','pelatihan-digital-mindset-asuransi','PT Asuransi Wira Sentosa','Jakarta Barat, DKI Jakarta',4,'{\"id\":\"Menyiapkan 210 karyawan menghadapi peralihan proses klaim ke sistem digital.\",\"en\":\"Preparing 210 employees for the shift of claims processing to a digital system.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Sistem klaim digital sudah dibeli tetapi pemakaiannya rendah. Sebagian besar karyawan tetap memproses klaim dengan berkas kertas karena merasa lebih aman.</p><h2>Pendekatan Kami</h2><p>Pelatihan tidak dimulai dari fitur sistem, melainkan dari kekhawatiran karyawan terhadap perubahan, baru kemudian menunjukkan bahwa proses digital menyelesaikan kekhawatiran itu.</p><h3>Lingkup Pengerjaan</h3><ul><li>Survei hambatan adopsi pada 210 karyawan.</li><li>Pelatihan 24 jam dengan praktik langsung pada sistem.</li><li>Pendampingan di meja kerja selama empat pekan pertama.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Pemakaian sistem digital naik dari 23% ke 88% dalam dua bulan.</li><li>Waktu proses klaim rata-rata turun dari 5 hari ke 2 hari.</li><li>Pemakaian berkas kertas untuk klaim dihentikan sepenuhnya.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Asuransi Wira Sentosa.</p>\",\"en\":\"<h2>Background</h2><p>A digital claims system had been purchased but adoption was low. Most staff kept processing claims on paper because it felt safer.</p><h2>Our Approach</h2><p>Training began not with system features but with employees\' worries about the change, then showed how the digital process addressed those worries.</p><h3>Scope of Work</h3><ul><li>Adoption-barrier survey across 210 employees.</li><li>24 hours of training with hands-on system practice.</li><li>Desk-side support during the first four weeks.</li></ul><h2>Results Achieved</h2><ul><li>Digital system usage rose from 23% to 88% within two months.</li><li>Average claim processing time fell from five days to two.</li><li>Paper-based claim files were discontinued entirely.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Asuransi Wira Sentosa.</p>\"}','banners/pc298heartznv8ieqsxyrcr2rbfuowuuhvyx70rx.webp','2025-08-11',0,16,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(20,'{\"id\":\"Pemetaan Jalur Karier BUMN\",\"en\":\"State-Owned Enterprise Career Path Mapping\"}','pemetaan-jalur-karier-bumn','PT Pelabuhan Niaga Indonesia','Surabaya, Jawa Timur',2,'{\"id\":\"Menyusun jalur karier yang jelas bagi 640 karyawan pada enam rumpun jabatan.\",\"en\":\"Designing clear career paths for 640 employees across six job families.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Karyawan tidak mengetahui syarat untuk naik jenjang, sehingga perpindahan jabatan dianggap ditentukan kedekatan. Survei keterikatan menempatkan kejelasan karier sebagai keluhan tertinggi.</p><h2>Pendekatan Kami</h2><p>Setiap rumpun jabatan dipetakan menjadi jalur bertingkat dengan syarat kompetensi dan pengalaman yang tertulis, lalu dipublikasikan agar setiap karyawan bisa membacanya sendiri.</p><h3>Lingkup Pengerjaan</h3><ul><li>Pengelompokan 640 jabatan ke dalam enam rumpun.</li><li>Penetapan syarat kompetensi tiap tingkat jalur karier.</li><li>Penyusunan panduan karier yang dibagikan ke seluruh karyawan.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Enam jalur karier resmi terbit dan dapat diakses karyawan.</li><li>Keluhan kejelasan karier turun dari peringkat 1 ke peringkat 7.</li><li>Permohonan mutasi yang sesuai syarat naik dua kali lipat.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Pelabuhan Niaga Indonesia.</p>\",\"en\":\"<h2>Background</h2><p>Employees did not know what was required to advance, so role changes were seen as decided by proximity. The engagement survey ranked career clarity as the top complaint.</p><h2>Our Approach</h2><p>Each job family was mapped into a tiered path with written competency and experience requirements, then published so every employee could read it directly.</p><h3>Scope of Work</h3><ul><li>Grouping 640 positions into six job families.</li><li>Defining competency requirements for each career tier.</li><li>Producing a career guide distributed to all employees.</li></ul><h2>Results Achieved</h2><ul><li>Six official career paths published and accessible to employees.</li><li>Career clarity complaints dropped from rank one to rank seven.</li><li>Qualifying transfer applications doubled.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Pelabuhan Niaga Indonesia.</p>\"}','banners/plq1ekwvxn5ci0wfwclmmv1tjy40gy2met4nydai.webp','2024-07-16',0,17,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(21,'{\"id\":\"Konsultasi Manajemen Risiko Tambang\",\"en\":\"Mining Risk Management Consulting\"}','konsultasi-manajemen-risiko-tambang','PT Mineral Jaya Abadi','Samarinda, Kalimantan Timur',1,'{\"id\":\"Membangun kerangka manajemen risiko operasional untuk tiga wilayah tambang.\",\"en\":\"Building an operational risk management framework for three mining areas.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Risiko dicatat terpisah oleh masing-masing departemen dengan format berbeda. Manajemen tidak pernah melihat gambaran risiko perusahaan secara utuh dalam satu dokumen.</p><h2>Pendekatan Kami</h2><p>Kami menyatukan seluruh catatan risiko ke dalam satu daftar dengan ukuran dampak dan kemungkinan yang sama, sehingga risiko dari departemen berbeda akhirnya dapat diperingkat bersama.</p><h3>Lingkup Pengerjaan</h3><ul><li>Penggabungan 11 catatan risiko departemen menjadi satu daftar.</li><li>Penetapan skala dampak dan kemungkinan yang seragam.</li><li>Pelatihan pemilik risiko di tiga wilayah tambang.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Satu daftar risiko perusahaan berisi 148 risiko terperingkat.</li><li>12 risiko tingkat tinggi memperoleh rencana mitigasi bernama penanggung jawab.</li><li>Tinjauan risiko menjadi agenda tetap rapat direksi triwulanan.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Mineral Jaya Abadi.</p>\",\"en\":\"<h2>Background</h2><p>Risks were logged separately by each department in different formats. Management never saw a whole-company risk picture in a single document.</p><h2>Our Approach</h2><p>We merged every risk log into a single register using one impact and likelihood scale, so risks from different departments could finally be ranked together.</p><h3>Scope of Work</h3><ul><li>Merging 11 departmental risk logs into one register.</li><li>Setting a uniform impact and likelihood scale.</li><li>Training risk owners across three mining areas.</li></ul><h2>Results Achieved</h2><ul><li>A single corporate register holding 148 ranked risks.</li><li>12 high-level risks gained mitigation plans with named owners.</li><li>Risk review became a standing item in quarterly board meetings.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Mineral Jaya Abadi.</p>\"}','banners/t0ik5rxnwidgrvbxk39rhukjmghhcfkb7qbq2frg.webp','2025-05-06',0,18,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(22,'{\"id\":\"Sertifikasi Juru Las Industri\",\"en\":\"Industrial Welder Certification\"}','sertifikasi-juru-las-industri','PT Fabrikasi Logam Nusantara','Batam, Kepulauan Riau',5,'{\"id\":\"Sertifikasi 120 juru las pada tiga posisi pengelasan sesuai permintaan pelanggan ekspor.\",\"en\":\"Certifying 120 welders in three welding positions as required by export customers.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Pelanggan ekspor mensyaratkan sertifikat juru las yang diakui untuk setiap posisi pengelasan. Tanpa itu, pesanan bernilai besar tidak dapat diambil.</p><h2>Pendekatan Kami</h2><p>Kemampuan setiap juru las diuji lebih dulu untuk menentukan siapa yang siap langsung diuji dan siapa yang perlu latihan tambahan, agar biaya pelatihan tidak dikeluarkan merata tanpa perlu.</p><h3>Lingkup Pengerjaan</h3><ul><li>Uji kemampuan awal 120 juru las pada tiga posisi.</li><li>Pelatihan tambahan bagi 44 juru las yang belum siap.</li><li>Uji kompetensi dan uji hasil las oleh pihak ketiga.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>114 juru las memperoleh sertifikat untuk minimal dua posisi.</li><li>Biaya pelatihan 37% lebih rendah dibanding rencana awal.</li><li>Pesanan ekspor yang tertunda dapat mulai dikerjakan.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Fabrikasi Logam Nusantara.</p>\",\"en\":\"<h2>Background</h2><p>Export customers required recognised welder certificates for each welding position. Without them, high-value orders could not be taken.</p><h2>Our Approach</h2><p>Every welder\'s skill was pre-tested to decide who could go straight to assessment and who needed extra practice, so training spend was not spread evenly without need.</p><h3>Scope of Work</h3><ul><li>Initial skill testing of 120 welders in three positions.</li><li>Extra training for 44 welders who were not yet ready.</li><li>Competency and weld-quality testing by a third party.</li></ul><h2>Results Achieved</h2><ul><li>114 welders certified in at least two positions.</li><li>Training cost came in 37% below the original plan.</li><li>The held export orders could finally begin production.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Fabrikasi Logam Nusantara.</p>\"}','banners/upsop00rdaphjpamgnyeyalvvxqjrnx6solj7a3b.webp','2024-11-08',0,19,1,'2026-09-14 08:14:06','2026-09-14 08:14:06'),(23,'{\"id\":\"Pencarian Direktur Keuangan\",\"en\":\"Finance Director Search\"}','executive-search-direktur-keuangan','PT Properti Cendana Group','Jakarta Selatan, DKI Jakarta',3,'{\"id\":\"Mencari direktur keuangan berpengalaman properti menjelang rencana penawaran saham perdana.\",\"en\":\"Finding a finance director with property experience ahead of a planned public offering.\"}','{\"id\":\"<h2>Latar Belakang</h2><p>Perusahaan bersiap melantai di bursa dan membutuhkan direktur keuangan yang pernah melalui proses serupa. Jumlah kandidat dengan pengalaman itu di sektor properti sangat terbatas.</p><h2>Pendekatan Kami</h2><p>Pencarian diperluas ke sektor bersebelahan yang memiliki pola pelaporan serupa, lalu setiap kandidat diuji pemahamannya atas persyaratan keterbukaan informasi emiten.</p><h3>Lingkup Pengerjaan</h3><ul><li>Pemetaan 31 kandidat dari sektor properti dan infrastruktur.</li><li>Asesmen kesiapan menghadapi proses penawaran saham perdana.</li><li>Pendampingan negosiasi paket dan masa transisi.</li></ul><h2>Hasil yang Dicapai</h2><ul><li>Posisi terisi dalam 13 pekan dengan kandidat berpengalaman emiten.</li><li>Empat kandidat final memenuhi seluruh syarat mutlak pemegang saham.</li><li>Masa transisi berjalan tanpa kekosongan fungsi keuangan.</li></ul><p>Pengerjaan ditutup dengan serah terima dokumen, rekaman pelatihan, dan sesi pendampingan lanjutan bagi tim internal PT Properti Cendana Group.</p>\",\"en\":\"<h2>Background</h2><p>The company was preparing to list and needed a finance director who had been through the process. Candidates with that experience in property were very few.</p><h2>Our Approach</h2><p>The search widened to adjacent sectors with similar reporting patterns, then every candidate was tested on issuer disclosure requirements.</p><h3>Scope of Work</h3><ul><li>Mapping 31 candidates from property and infrastructure.</li><li>Assessing readiness for the public offering process.</li><li>Package negotiation and transition support.</li></ul><h2>Results Achieved</h2><ul><li>The role was filled in 13 weeks by a candidate with issuer experience.</li><li>All four finalists met every shareholder hard requirement.</li><li>The handover ran with no gap in the finance function.</li></ul><p>The engagement closed with document handover, training records, and a follow-up coaching session for the internal team at PT Properti Cendana Group.</p>\"}','banners/w712tyfbgfkeiduupat9ii06xkayevlr9ay3psim.webp','2025-09-02',0,20,1,'2026-09-14 08:14:06','2026-09-14 08:14:06');
