INSERT INTO `service_activities` (`id`, `service_id`, `title`, `description`, `sort_order`, `created_at`, `updated_at`) VALUES (161,1,'{\"id\":\"Dasar hukum dan kebijakan K3\",\"en\":\"Safety law and policy foundations\"}','{\"id\":\"Peraturan perundangan K3, kewajiban perusahaan, dan peran Ahli K3 di tempat kerja.\",\"en\":\"Safety legislation, company obligations, and the safety expert\'s role in the workplace.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(162,1,'{\"id\":\"Identifikasi bahaya dan penilaian risiko\",\"en\":\"Hazard identification and risk assessment\"}','{\"id\":\"Teknik HIRADC dan penyusunan pengendalian risiko yang dapat dijalankan di lapangan.\",\"en\":\"HIRADC technique and designing risk controls that work on the ground.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(163,1,'{\"id\":\"Praktik inspeksi dan investigasi insiden\",\"en\":\"Inspection and incident investigation practice\"}','{\"id\":\"Kunjungan lapangan, pencatatan temuan, dan penelusuran akar penyebab insiden.\",\"en\":\"Site visits, recording findings, and tracing incident root causes.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(164,1,'{\"id\":\"Simulasi dan uji kompetensi\",\"en\":\"Simulation and assessment\"}','{\"id\":\"Dua kali simulasi ujian, pembahasan, lalu uji kompetensi bersama asesor BNSP.\",\"en\":\"Two mock exams, review, then assessment with a BNSP assessor.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(165,2,'{\"id\":\"Peran supervisor sebagai penghubung\",\"en\":\"The supervisor as a bridge\"}','{\"id\":\"Memahami posisi supervisor di antara manajemen dan tim, serta tanggung jawab yang melekat padanya.\",\"en\":\"Understanding the supervisor\'s position between management and team, and the responsibilities that come with it.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(166,2,'{\"id\":\"Percakapan sulit dan umpan balik\",\"en\":\"Difficult conversations and feedback\"}','{\"id\":\"Latihan menyampaikan koreksi tanpa merusak hubungan kerja, dengan permainan peran berpasangan.\",\"en\":\"Practice delivering correction without damaging the working relationship, through paired role-play.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(167,2,'{\"id\":\"Pembagian tugas dan pengawasan\",\"en\":\"Delegation and oversight\"}','{\"id\":\"Menentukan apa yang boleh diserahkan, kepada siapa, dan bagaimana memantaunya tanpa mengambil alih.\",\"en\":\"Deciding what to hand over, to whom, and how to monitor without taking back over.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(168,2,'{\"id\":\"Proyek perbaikan unit\",\"en\":\"Unit improvement project\"}','{\"id\":\"Setiap peserta menjalankan satu perbaikan nyata di unitnya dan memaparkan hasilnya.\",\"en\":\"Each participant runs one real improvement in their unit and presents the result.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(169,3,'{\"id\":\"Penyusunan kamus kompetensi\",\"en\":\"Competency dictionary design\"}','{\"id\":\"Menetapkan perilaku apa yang dinilai dan bagaimana tingkatannya dibedakan.\",\"en\":\"Defining which behaviours are assessed and how levels are distinguished.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(170,3,'{\"id\":\"Simulasi in-tray dan studi kasus\",\"en\":\"In-tray and case study simulation\"}','{\"id\":\"Peserta menangani tumpukan pekerjaan tiruan dalam batas waktu, diamati asesor.\",\"en\":\"Participants handle a simulated workload against the clock, observed by assessors.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(171,3,'{\"id\":\"Diskusi kelompok terarah\",\"en\":\"Focus group discussion\"}','{\"id\":\"Menilai cara peserta memengaruhi, mendengarkan, dan mengambil keputusan bersama.\",\"en\":\"Assessing how participants influence, listen, and decide together.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(172,3,'{\"id\":\"Penyusunan laporan dan umpan balik\",\"en\":\"Reporting and feedback\"}','{\"id\":\"Kalibrasi antarasesor, penulisan laporan, lalu penyampaian hasil kepada peserta.\",\"en\":\"Assessor calibration, report writing, then delivering results to participants.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(173,4,'{\"id\":\"Penyelarasan kriteria jabatan\",\"en\":\"Role criteria alignment\"}','{\"id\":\"Menyepakati syarat mutlak dan syarat yang masih bisa dinegosiasikan bersama pemberi kerja.\",\"en\":\"Agreeing hard requirements and negotiable ones with the employer.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(174,4,'{\"id\":\"Pemetaan dan pendekatan kandidat\",\"en\":\"Candidate mapping and approach\"}','{\"id\":\"Menyusun daftar panjang dari perusahaan sejenis lalu melakukan pendekatan tertutup.\",\"en\":\"Building a long list from comparable companies then approaching confidentially.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(175,4,'{\"id\":\"Asesmen dan wawancara berbasis perilaku\",\"en\":\"Assessment and behaviour-based interviews\"}','{\"id\":\"Menguji kompetensi kepemimpinan dan kecocokan dengan budaya organisasi.\",\"en\":\"Testing leadership competency and fit with the organisation\'s culture.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(176,4,'{\"id\":\"Pendampingan penawaran dan masa transisi\",\"en\":\"Offer and transition support\"}','{\"id\":\"Membantu negosiasi paket sampai kandidat terpilih benar-benar mulai bekerja.\",\"en\":\"Supporting package negotiation until the selected candidate actually starts.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(177,5,'{\"id\":\"Penelusuran proses kerja\",\"en\":\"Work process tracing\"}','{\"id\":\"Wawancara dan observasi langsung untuk memetakan pekerjaan nyata tiap unit.\",\"en\":\"Interviews and direct observation to map each unit\'s real work.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(178,5,'{\"id\":\"Analisis hambatan keputusan\",\"en\":\"Decision bottleneck analysis\"}','{\"id\":\"Menemukan titik persetujuan yang tidak menambah nilai dan memperlambat proses.\",\"en\":\"Finding approval points that add no value and slow things down.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(179,5,'{\"id\":\"Perancangan struktur dan wewenang\",\"en\":\"Structure and authority design\"}','{\"id\":\"Menyusun struktur baru dan menurunkan wewenang ke jenjang yang tepat.\",\"en\":\"Designing the new structure and pushing authority to the right level.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(180,5,'{\"id\":\"Penerapan dan pendampingan\",\"en\":\"Rollout and support\"}','{\"id\":\"Sosialisasi ke seluruh karyawan dan pendampingan sampai struktur berjalan.\",\"en\":\"Briefing all employees and supporting the structure until it runs.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(181,6,'{\"id\":\"Perencanaan dan pengadaan SDM\",\"en\":\"HR planning and resourcing\"}','{\"id\":\"Menyusun kebutuhan tenaga kerja dan menjalankan proses seleksi yang tertelusur.\",\"en\":\"Planning workforce needs and running a traceable selection process.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(182,6,'{\"id\":\"Pengelolaan kinerja dan pengembangan\",\"en\":\"Performance and development management\"}','{\"id\":\"Merancang sasaran kerja, penilaian, dan rencana pengembangan karyawan.\",\"en\":\"Designing work targets, appraisals, and employee development plans.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(183,6,'{\"id\":\"Hubungan industrial dan kepatuhan\",\"en\":\"Industrial relations and compliance\"}','{\"id\":\"Penerapan ketentuan ketenagakerjaan dan penanganan perselisihan hubungan kerja.\",\"en\":\"Applying labour provisions and handling employment disputes.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(184,6,'{\"id\":\"Penyusunan portofolio dan uji kompetensi\",\"en\":\"Portfolio preparation and assessment\"}','{\"id\":\"Mengumpulkan bukti kerja nyata lalu menjalani uji bersama asesor BNSP.\",\"en\":\"Gathering real work evidence then sitting the assessment with a BNSP assessor.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(185,7,'{\"id\":\"Observasi layanan di tempat kerja\",\"en\":\"On-site service observation\"}','{\"id\":\"Mengamati praktik nyata di titik layanan untuk menemukan kesenjangan mutu.\",\"en\":\"Observing real practice at service points to find quality gaps.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(186,7,'{\"id\":\"Penyusunan standar layanan\",\"en\":\"Service standard development\"}','{\"id\":\"Mengangkat praktik terbaik internal menjadi standar yang bisa dilatihkan.\",\"en\":\"Turning internal best practice into a teachable standard.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(187,7,'{\"id\":\"Latihan penanganan keluhan\",\"en\":\"Complaint handling practice\"}','{\"id\":\"Permainan peran menghadapi keluhan sulit, dengan umpan balik langsung.\",\"en\":\"Role-play against difficult complaints with immediate feedback.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(188,7,'{\"id\":\"Pembekalan pelatih internal\",\"en\":\"Internal trainer briefing\"}','{\"id\":\"Menyiapkan staf terpilih agar mampu menyegarkan materi ini sendiri.\",\"en\":\"Preparing selected staff to refresh this material themselves.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(189,8,'{\"id\":\"Penurunan sasaran perusahaan\",\"en\":\"Company target cascading\"}','{\"id\":\"Menerjemahkan sasaran direksi menjadi sasaran departemen yang terukur.\",\"en\":\"Translating board targets into measurable departmental goals.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(190,8,'{\"id\":\"Penyusunan KPI per jabatan\",\"en\":\"Per-role KPI design\"}','{\"id\":\"Menetapkan indikator yang benar-benar dikendalikan pemegang jabatan.\",\"en\":\"Setting indicators the role-holder genuinely controls.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(191,8,'{\"id\":\"Kajian pembanding gaji\",\"en\":\"Salary benchmarking\"}','{\"id\":\"Membandingkan struktur gaji terhadap data pasar industri sejenis.\",\"en\":\"Comparing the pay structure against comparable industry market data.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(192,8,'{\"id\":\"Penerapan dan komunikasi\",\"en\":\"Rollout and communication\"}','{\"id\":\"Menyiapkan cara menjelaskan struktur baru kepada seluruh karyawan.\",\"en\":\"Preparing how to explain the new structure to all employees.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(193,9,'{\"id\":\"Verifikasi kelayakan tempat uji\",\"en\":\"Assessment venue verification\"}','{\"id\":\"Memastikan peralatan dan lokasi memenuhi syarat sebagai tempat uji kompetensi.\",\"en\":\"Ensuring equipment and location meet assessment venue requirements.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(194,9,'{\"id\":\"Uji kemampuan awal\",\"en\":\"Initial skill testing\"}','{\"id\":\"Memisahkan peserta yang siap langsung diuji dari yang perlu latihan tambahan.\",\"en\":\"Separating those ready for assessment from those needing extra practice.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(195,9,'{\"id\":\"Pelatihan penyegaran\",\"en\":\"Refresher training\"}','{\"id\":\"Latihan terarah pada kelemahan yang ditemukan di uji kemampuan awal.\",\"en\":\"Targeted practice on the weaknesses found in initial testing.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(196,9,'{\"id\":\"Uji kompetensi dan penerbitan sertifikat\",\"en\":\"Assessment and certification\"}','{\"id\":\"Uji praktik bersama asesor, pemeriksaan mutu hasil, lalu penerbitan sertifikat.\",\"en\":\"Practical assessment with an assessor, quality inspection, then certificate issuance.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(197,10,'{\"id\":\"Analisis catatan insiden\",\"en\":\"Incident record analysis\"}','{\"id\":\"Menelusuri pola insiden di lokasi untuk menentukan prioritas materi.\",\"en\":\"Tracing site incident patterns to set material priorities.\"}',1,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(198,10,'{\"id\":\"Kelas identifikasi bahaya\",\"en\":\"Hazard identification class\"}','{\"id\":\"Melatih pekerja mengenali dan melaporkan bahaya sebelum menjadi insiden.\",\"en\":\"Training workers to spot and report hazards before they become incidents.\"}',2,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(199,10,'{\"id\":\"Latihan tanggap darurat\",\"en\":\"Emergency drill\"}','{\"id\":\"Simulasi kebakaran, tumpahan, dan evakuasi sesuai kondisi lokasi.\",\"en\":\"Fire, spill, and evacuation simulation matched to site conditions.\"}',3,'2026-09-14 08:39:00','2026-09-14 08:39:00'),(200,10,'{\"id\":\"Evaluasi dan penyusunan tindak lanjut\",\"en\":\"Evaluation and follow-up planning\"}','{\"id\":\"Menilai hasil latihan dan menyusun perbaikan yang perlu dijalankan.\",\"en\":\"Assessing drill results and planning the improvements to be made.\"}',4,'2026-09-14 08:39:00','2026-09-14 08:39:00');
