INSERT INTO `service_categories` (`id`, `name`, `slug`, `short_description`, `description`, `icon`, `image`, `is_featured`, `sort_order`, `is_active`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES (1,'{\"id\":\"Konsultasi Manajemen\",\"en\":\"Management Consulting\"}','konsultasi-manajemen','{\"id\":\"Menata struktur organisasi, alur wewenang, dan uraian tugas agar keputusan tidak tersendat di banyak lapis.\",\"en\":\"Reshaping structure, authority flow, and job descriptions so decisions stop stalling across layers.\"}',NULL,NULL,'service-categories/68smsykzc0qykwh06nmbtbptqnzhzkdmlsf46kjv.webp',1,1,1,NULL,NULL,'2026-09-14 07:41:33','2026-09-14 15:09:27'),(2,'{\"id\":\"Konsultasi Manajemen Human Capital\",\"en\":\"Human Capital Management Consulting\"}','konsultasi-manajemen-human-capital','{\"id\":\"Memetakan kompetensi, menyiapkan suksesi jabatan kunci, dan menyusun KPI beserta struktur remunerasinya.\",\"en\":\"Mapping competencies, preparing succession for key roles, and designing KPIs with their pay structure.\"}',NULL,NULL,'service-categories/dmury8flxg4aaqswv9xvt7ljli1t4zikw1pilpic.webp',1,2,1,NULL,NULL,'2026-09-14 07:41:33','2026-09-14 15:09:27'),(3,'{\"id\":\"Headhunter\",\"en\":\"Headhunter\"}','headhunter','{\"id\":\"Pencarian tertutup untuk posisi manajerial dan direksi yang sulit diisi lewat lowongan terbuka.\",\"en\":\"Confidential search for managerial and board roles that open advertising cannot fill.\"}',NULL,NULL,'service-categories/fx5bqw3etxkvh658kjkkcbhwjbjam2llgtrus3yp.webp',1,3,1,NULL,NULL,'2026-09-14 07:41:33','2026-09-14 15:09:27'),(4,'{\"id\":\"Pelatihan Karyawan\",\"en\":\"Employee Training\"}','pelatihan-karyawan','{\"id\":\"Program in-house yang materinya disusun dari pekerjaan peserta sehari-hari, bukan dari katalog siap pakai.\",\"en\":\"In-house programmes built from participants\' own daily work rather than an off-the-shelf catalogue.\"}',NULL,NULL,'service-categories/ld4pbk6zc5tfkxhqlw5qfv3jwknq1qsee9j87xd3.webp',1,4,1,NULL,NULL,'2026-09-14 07:41:33','2026-09-14 15:09:27'),(5,'{\"id\":\"Sertifikasi Kompetensi\",\"en\":\"Competency Certification\"}','sertifikasi-kompetensi','{\"id\":\"Uji kompetensi skema BNSP yang dapat digelar di tempat kerja Anda, mengikuti pola sif, tanpa menghentikan produksi.\",\"en\":\"BNSP-scheme assessment that can run at your workplace, around your shift pattern, without stopping production.\"}',NULL,NULL,'service-categories/nrgvvhnrjhoihchdlzkgtvsqnpsquedr1hceb5ik.webp',1,5,1,NULL,NULL,'2026-09-14 07:41:33','2026-09-14 15:09:27');
