INSERT INTO `services` (`id`, `service_category_id`, `title`, `slug`, `short_description`, `description`, `image`, `price`, `discount_active`, `discount_original_price`, `price_label`, `duration`, `location`, `mode`, `quota`, `seats_taken`, `is_purchasable`, `is_featured`, `sort_order`, `is_active`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES (1,5,'{\"id\":\"Sertifikasi BNSP Ahli K3 Umum\",\"en\":\"BNSP General Safety Expert Certification\"}','sertifikasi-bnsp-ahli-k3-umum','{\"id\":\"Pelatihan 120 jam dan uji kompetensi untuk memperoleh sertifikat Ahli K3 Umum.\",\"en\":\"120 hours of training and assessment leading to General Safety Expert certification.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Program ini menyiapkan peserta menghadapi uji kompetensi Ahli K3 Umum sesuai skema BNSP. Materi disusun mengikuti unit kompetensi resmi, dengan porsi latihan soal dan studi kasus lapangan yang lebih besar dibanding kelas teori biasa.</p><h2>Untuk Siapa Program Ini</h2><p>Pengawas lapangan, staf K3, dan calon petugas K3 di industri konstruksi, manufaktur, serta minyak dan gas yang perusahaannya mensyaratkan Ahli K3 bersertifikat.</p><h2>Yang Anda Dapatkan</h2><ul><li>Modul cetak dan digital seluruh unit kompetensi.</li><li>Dua kali simulasi ujian lengkap dengan pembahasan.</li><li>Uji kompetensi BNSP dan sertifikat bagi yang dinyatakan kompeten.</li><li>Pendampingan penyusunan laporan praktik kerja lapangan.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>This programme prepares participants for the General Safety Expert assessment under the BNSP scheme. Material follows the official competency units, with more exam practice and field case work than a standard theory class.</p><h2>Who This Is For</h2><p>Field supervisors, safety staff, and prospective safety officers in construction, manufacturing, and oil and gas whose companies require certified safety experts.</p><h2>What You Receive</h2><ul><li>Printed and digital modules for every competency unit.</li><li>Two full mock examinations with discussion.</li><li>BNSP assessment and a certificate for those judged competent.</li><li>Support in preparing the field practice report.</li></ul>\"}','services/femt61x5fku1xeo71dcnez3elsbke6pe4hzgltpm.webp',8500000.00,1,12500000.00,'{\"id\":null}','{\"id\":\"12 hari (120 jam)\",\"en\":\"12 days (120 hours)\"}','Jakarta Selatan, DKI Jakarta','offline',25,14,1,1,1,1,NULL,NULL,'2026-09-14 02:00:00','2026-09-14 08:29:04'),(2,4,'{\"id\":\"Pelatihan Kepemimpinan untuk Supervisor\",\"en\":\"Leadership Training for Supervisors\"}','pelatihan-kepemimpinan-supervisor','{\"id\":\"Membekali supervisor baru dengan keterampilan memimpin tim, bukan sekadar keahlian teknis.\",\"en\":\"Equipping new supervisors with team leadership skills, not just technical expertise.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Banyak supervisor diangkat karena mahir secara teknis, lalu kesulitan saat harus memimpin orang. Program ini menutup jarak itu melalui latihan percakapan sulit, pemberian umpan balik, dan pembagian tugas yang dilatih berulang dalam kelas.</p><h2>Untuk Siapa Program Ini</h2><p>Supervisor yang baru diangkat dalam dua tahun terakhir, serta calon supervisor yang sedang disiapkan naik jenjang.</p><h2>Yang Anda Dapatkan</h2><ul><li>Buku kerja berisi lembar latihan yang dapat dipakai kembali di unit masing-masing.</li><li>Umpan balik 360 derajat sebelum dan sesudah program.</li><li>Rencana pengembangan pribadi untuk tiga bulan berikutnya.</li><li>Sertifikat kepesertaan.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>Many supervisors are promoted for technical skill, then struggle when they must lead people. This programme closes that gap through repeated practice in difficult conversations, feedback, and delegation.</p><h2>Who This Is For</h2><p>Supervisors promoted within the last two years, and candidates being prepared for the step up.</p><h2>What You Receive</h2><ul><li>A workbook of practice sheets reusable back in each participant\'s unit.</li><li>360-degree feedback before and after the programme.</li><li>A personal development plan for the next three months.</li><li>Certificate of attendance.</li></ul>\"}','services/gzefafk6sptj1kqryp3d9evmmvpd1raeseiqyfkv.webp',4500000.00,1,6000000.00,'{\"id\":null}','{\"id\":\"4 hari (32 jam)\",\"en\":\"4 days (32 hours)\"}','Jakarta Pusat, DKI Jakarta','offline',30,21,1,1,2,1,NULL,NULL,'2026-09-13 02:00:00','2026-09-14 08:29:04'),(3,2,'{\"id\":\"Assessment Center dan Talent Mapping\",\"en\":\"Assessment Centre and Talent Mapping\"}','assessment-center-dan-talent-mapping','{\"id\":\"Menilai kesiapan karyawan naik jenjang dengan metode yang sama dan dapat dibandingkan.\",\"en\":\"Assessing employees\' readiness to advance using one comparable method.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Layanan ini menilai kompetensi karyawan melalui simulasi kerja, bukan hanya wawancara. Setiap peserta melalui rangkaian latihan yang sama dan dinilai asesor bersertifikat, sehingga hasil antarpeserta benar-benar setara.</p><h2>Untuk Siapa Program Ini</h2><p>Perusahaan yang sedang menyiapkan suksesi jabatan kunci, atau yang ingin keputusan promosinya berdiri di atas dasar yang dapat dipertanggungjawabkan.</p><h2>Yang Anda Dapatkan</h2><ul><li>Kamus kompetensi khusus untuk jenjang yang dinilai.</li><li>Laporan individual berisi kekuatan, kesenjangan, dan saran pengembangan.</li><li>Peta talenta kisi sembilan kotak untuk seluruh peserta.</li><li>Sesi umpan balik tatap muka bagi setiap peserta.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>This service assesses competency through work simulations, not interviews alone. Every participant goes through the same exercise set scored by certified assessors, so results are genuinely comparable.</p><h2>Who This Is For</h2><p>Companies preparing succession for key roles, or those wanting promotion decisions to rest on defensible ground.</p><h2>What You Receive</h2><ul><li>A competency dictionary tailored to the level being assessed.</li><li>Individual reports covering strengths, gaps, and development advice.</li><li>A nine-box talent grid covering all participants.</li><li>A face-to-face feedback session for every participant.</li></ul>\"}','services/lxmtmhowf2ahkenbnuli0ptj43npawzmlabjiddq.webp',3200000.00,0,NULL,'{\"id\":null}','{\"id\":\"2 hari per angkatan\",\"en\":\"2 days per cohort\"}','Jakarta Selatan, DKI Jakarta','offline',20,12,1,1,3,1,NULL,NULL,'2026-09-12 02:00:00','2026-09-14 08:29:04'),(4,3,'{\"id\":\"Layanan Headhunter Eksekutif\",\"en\":\"Executive Headhunter Service\"}','layanan-headhunter-eksekutif','{\"id\":\"Pencarian tertutup untuk posisi manajerial dan direksi yang sulit diisi lewat lowongan terbuka.\",\"en\":\"Confidential search for managerial and board roles that open advertising cannot fill.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Kami memetakan kandidat langsung dari perusahaan sejenis, bukan menunggu lamaran masuk. Pendekatan dilakukan tertutup sehingga proses tidak terbaca pasar dan kandidat yang sedang menjabat tetap nyaman berbicara.</p><h2>Untuk Siapa Program Ini</h2><p>Perusahaan yang membutuhkan posisi manajer senior ke atas, terutama untuk peran yang langka atau berada di lokasi yang sulit menarik kandidat.</p><h2>Yang Anda Dapatkan</h2><ul><li>Laporan pemetaan pasar kandidat beserta pembanding remunerasi.</li><li>Daftar pendek berisi 3–5 kandidat lengkap dengan hasil asesmen.</li><li>Penelusuran rekam jejak dari minimal dua sumber.</li><li>Masa garansi penggantian 12 bulan.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>We map candidates directly from comparable companies rather than waiting for applications. Approaches stay confidential so the process stays off the market and sitting executives remain comfortable talking.</p><h2>Who This Is For</h2><p>Companies needing senior manager roles and above, especially scarce positions or sites that struggle to attract candidates.</p><h2>What You Receive</h2><ul><li>A candidate market map with remuneration benchmarks.</li><li>A shortlist of three to five candidates with assessment results.</li><li>Reference checks from at least two sources.</li><li>A 12-month replacement guarantee.</li></ul>\"}','services/lzcyq8f102jcypd8dz77hrqiryispkqxijxch78r.webp',38500000.00,1,52000000.00,'{\"id\":\"penugasan\",\"en\":\"assignment\"}','{\"id\":\"8–14 pekan\",\"en\":\"8–14 weeks\"}','Jakarta Selatan, DKI Jakarta','hybrid',6,4,1,1,4,1,NULL,NULL,'2026-09-11 02:00:00','2026-09-14 08:29:04'),(5,1,'{\"id\":\"Konsultasi Struktur Organisasi\",\"en\":\"Organisational Structure Consulting\"}','konsultasi-struktur-organisasi','{\"id\":\"Menata ulang struktur, uraian tugas, dan alur wewenang agar keputusan tidak tersendat.\",\"en\":\"Rebuilding structure, job descriptions, and authority flow so decisions stop stalling.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Kami menelusuri apa yang benar-benar dikerjakan tiap unit sebelum menggambar struktur baru. Dengan begitu, struktur yang dihasilkan menjawab hambatan nyata di lapangan, bukan sekadar merapikan bagan di atas kertas.</p><h2>Untuk Siapa Program Ini</h2><p>Perusahaan yang tumbuh cepat sehingga strukturnya tidak lagi seimbang, atau yang sedang menyiapkan akreditasi dan audit yang menyoroti uraian tugas.</p><h2>Yang Anda Dapatkan</h2><ul><li>Peta alur persetujuan pada seluruh proses inti.</li><li>Rancangan struktur baru beserta matriks wewenang.</li><li>Uraian tugas tertulis untuk setiap jabatan terdampak.</li><li>Pendampingan masa transisi selama tiga bulan.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>We trace what each unit actually does before drawing a new structure, so the result answers real bottlenecks rather than merely tidying a chart on paper.</p><h2>Who This Is For</h2><p>Fast-growing companies whose structure has fallen out of balance, or those preparing for accreditation and audits that scrutinise job descriptions.</p><h2>What You Receive</h2><ul><li>An approval-flow map across all core processes.</li><li>A new structure design with an authority matrix.</li><li>Written job descriptions for every affected position.</li><li>Three months of transition support.</li></ul>\"}','services/rkovyxkjkjgzy4bqtvf41uxwsmfvaqizutolyix1.webp',72000000.00,1,90000000.00,'{\"id\":\"paket proyek\",\"en\":\"project package\"}','{\"id\":\"3–6 bulan\",\"en\":\"3–6 months\"}','Di lokasi klien','offline',4,2,1,0,5,1,NULL,NULL,'2026-09-10 02:00:00','2026-09-14 08:29:04'),(6,5,'{\"id\":\"Sertifikasi BNSP Bidang Human Resource\",\"en\":\"BNSP Human Resource Certification\"}','sertifikasi-bnsp-human-resource','{\"id\":\"Uji kompetensi bagi praktisi SDM pada skema staf, supervisor, dan manajer.\",\"en\":\"Assessment for HR practitioners across staff, supervisor, and manager schemes.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Program ini menyiapkan praktisi SDM menghadapi uji kompetensi sesuai jenjangnya, mulai dari administrasi kepegawaian sampai perancangan sistem pengelolaan kinerja. Setiap unit kompetensi dilatih dengan berkas kerja nyata.</p><h2>Untuk Siapa Program Ini</h2><p>Staf hingga manajer SDM yang membutuhkan pengakuan kompetensi resmi, termasuk untuk keperluan kenaikan jenjang internal.</p><h2>Yang Anda Dapatkan</h2><ul><li>Modul per unit kompetensi sesuai jenjang yang diambil.</li><li>Pendampingan penyusunan portofolio bukti kompetensi.</li><li>Uji kompetensi BNSP dan sertifikat bagi yang kompeten.</li><li>Akses rekaman kelas selama enam bulan.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>This programme prepares HR practitioners for assessment at their level, from personnel administration through to performance management system design. Every competency unit is practised with real working documents.</p><h2>Who This Is For</h2><p>HR staff through to managers needing formal competency recognition, including for internal advancement.</p><h2>What You Receive</h2><ul><li>Modules per competency unit for the chosen level.</li><li>Support in compiling the competency evidence portfolio.</li><li>BNSP assessment and certificate for those judged competent.</li><li>Six months of access to class recordings.</li></ul>\"}','services/v5g2xzqolndsss6vcx1jrajtvusjleaejzglhk07.webp',6500000.00,0,NULL,'{\"id\":null}','{\"id\":\"6 hari (48 jam)\",\"en\":\"6 days (48 hours)\"}','Jakarta Selatan, DKI Jakarta','hybrid',25,9,1,0,6,1,NULL,NULL,'2026-09-09 02:00:00','2026-09-14 08:29:04'),(7,4,'{\"id\":\"Pelatihan Layanan Pelanggan\",\"en\":\"Customer Service Training\"}','pelatihan-layanan-pelanggan','{\"id\":\"Menyeragamkan mutu layanan garis depan melalui standar dan latihan penanganan keluhan.\",\"en\":\"Standardising front-line service quality through standards and complaint-handling practice.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Program ini berangkat dari praktik terbaik yang sudah ada di dalam perusahaan Anda sendiri, diangkat menjadi standar tertulis, lalu dilatihkan ke seluruh staf garis depan agar mutunya tidak lagi bergantung pada siapa yang bertugas.</p><h2>Untuk Siapa Program Ini</h2><p>Staf toko, resepsionis, petugas layanan pelanggan, dan siapa pun yang berhadapan langsung dengan pelanggan setiap hari.</p><h2>Yang Anda Dapatkan</h2><ul><li>Standar layanan tertulis khusus untuk perusahaan Anda.</li><li>Naskah penanganan keluhan untuk situasi yang paling sering terjadi.</li><li>Pembekalan pelatih internal untuk penyegaran mandiri.</li><li>Lembar penilaian layanan untuk pemantauan berkala.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>The programme starts from best practice already present inside your own company, turns it into a written standard, then trains it across all front-line staff so quality no longer depends on who is on duty.</p><h2>Who This Is For</h2><p>Store staff, receptionists, customer service officers, and anyone facing customers daily.</p><h2>What You Receive</h2><ul><li>A written service standard specific to your company.</li><li>Complaint-handling scripts for the most frequent situations.</li><li>Internal trainer briefing for self-run refreshers.</li><li>A service scoring sheet for periodic monitoring.</li></ul>\"}','services/yn5u0f42arnshv2mfsowkkmatavh14e4038ets3j.webp',3500000.00,0,NULL,'{\"id\":null}','{\"id\":\"3 hari (24 jam)\",\"en\":\"3 days (24 hours)\"}','Tangerang, Banten','offline',30,18,1,0,7,1,NULL,NULL,'2026-09-08 02:00:00','2026-09-14 08:29:05'),(8,2,'{\"id\":\"Penyusunan KPI dan Sistem Remunerasi\",\"en\":\"KPI and Remuneration System Design\"}','penyusunan-kpi-dan-remunerasi','{\"id\":\"Menghubungkan sasaran perusahaan ke penilaian individu dan struktur gaji yang jelas.\",\"en\":\"Connecting company targets to individual appraisal and a clear pay structure.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Layanan ini menurunkan sasaran perusahaan sampai ke KPI tiap jabatan, lalu menyusun ulang struktur gaji dengan rentang yang jelas per jenjang. Hasilnya, kenaikan gaji punya dasar yang bisa dijelaskan kepada karyawan.</p><h2>Untuk Siapa Program Ini</h2><p>Perusahaan yang kenaikan gajinya masih merata tanpa kaitan pencapaian, atau yang kehilangan karyawan berkinerja tinggi karena merasa tidak dihargai.</p><h2>Yang Anda Dapatkan</h2><ul><li>Peta penurunan sasaran dari perusahaan sampai individu.</li><li>Kamus KPI untuk seluruh jenjang jabatan.</li><li>Struktur gaji dengan rentang per jenjang beserta kajian pembandingnya.</li><li>Panduan penerapan untuk tim SDM internal.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>This service cascades company targets down to per-role KPIs, then rebuilds the pay structure with clear ranges per level. Pay rises then have a basis that can be explained to employees.</p><h2>Who This Is For</h2><p>Companies still granting flat pay rises unconnected to achievement, or losing high performers who feel unrecognised.</p><h2>What You Receive</h2><ul><li>A target cascade map from company down to individual.</li><li>A KPI dictionary covering all job levels.</li><li>A pay structure with ranges per level plus benchmarking analysis.</li><li>An implementation guide for the internal HR team.</li></ul>\"}','service-categories/68smsykzc0qykwh06nmbtbptqnzhzkdmlsf46kjv.webp',48000000.00,1,60000000.00,'{\"id\":\"paket proyek\",\"en\":\"project package\"}','{\"id\":\"2–4 bulan\",\"en\":\"2–4 months\"}','Di lokasi klien','hybrid',5,3,1,0,8,1,NULL,NULL,'2026-09-07 02:00:00','2026-09-14 08:29:05'),(9,5,'{\"id\":\"Sertifikasi Juru Las dan Teknisi\",\"en\":\"Welder and Technician Certification\"}','sertifikasi-juru-las-dan-teknisi','{\"id\":\"Uji kompetensi bidang teknik yang dapat digelar langsung di lokasi kerja Anda.\",\"en\":\"Technical competency assessment that can run directly at your workplace.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Uji kompetensi digelar di tempat kerja pada mesin dan peralatan yang benar-benar dioperasikan peserta. Pola ini menghemat waktu produksi sekaligus memastikan yang diuji adalah keterampilan yang dipakai sehari-hari.</p><h2>Untuk Siapa Program Ini</h2><p>Perusahaan manufaktur, fabrikasi, dan konstruksi yang pelanggannya mensyaratkan juru las atau teknisi bersertifikat.</p><h2>Yang Anda Dapatkan</h2><ul><li>Uji kemampuan awal untuk menentukan kesiapan tiap peserta.</li><li>Pelatihan tambahan hanya bagi peserta yang membutuhkan.</li><li>Uji kompetensi di tempat kerja dan sertifikat BNSP.</li><li>Arsip bukti kompetensi siap untuk keperluan audit.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>Assessment runs at the workplace on the machines participants actually operate. This saves production time while ensuring the skills tested are the ones used daily.</p><h2>Who This Is For</h2><p>Manufacturing, fabrication, and construction companies whose customers require certified welders or technicians.</p><h2>What You Receive</h2><ul><li>Initial skill testing to gauge each participant\'s readiness.</li><li>Extra training only for participants who need it.</li><li>On-site assessment and BNSP certification.</li><li>A competency evidence archive ready for audit.</li></ul>\"}','service-categories/dmury8flxg4aaqswv9xvt7ljli1t4zikw1pilpic.webp',3800000.00,1,4750000.00,'{\"id\":null}','{\"id\":\"5 hari (40 jam)\",\"en\":\"5 days (40 hours)\"}','Di lokasi klien','offline',40,27,1,0,9,1,NULL,NULL,'2026-09-06 02:00:00','2026-09-14 08:29:05'),(10,4,'{\"id\":\"Pelatihan K3 dan Tanggap Darurat\",\"en\":\"Safety and Emergency Response Training\"}','pelatihan-k3-dan-tanggap-darurat','{\"id\":\"Pelatihan keselamatan yang materinya disusun dari catatan insiden di lokasi Anda sendiri.\",\"en\":\"Safety training built from incident records at your own site.\"}','{\"id\":\"<h2>Tentang Program Ini</h2><p>Alih-alih memakai materi induksi umum, kami menyusun ulang bahan pelatihan dari catatan insiden dan nyaris celaka yang pernah terjadi di lokasi Anda. Bahaya yang dibahas menjadi bahaya yang benar-benar dikenali peserta.</p><h2>Untuk Siapa Program Ini</h2><p>Pekerja lapangan, pengawas, dan tim tanggap darurat di industri dengan risiko kerja tinggi.</p><h2>Yang Anda Dapatkan</h2><ul><li>Analisis catatan insiden dan nyaris celaka dua tahun terakhir.</li><li>Materi induksi baru yang dapat dipakai permanen untuk pekerja masuk.</li><li>Latihan tanggap darurat dengan skenario lokasi nyata.</li><li>Laporan kesiapan tanggap darurat beserta rekomendasi.</li></ul>\",\"en\":\"<h2>About This Programme</h2><p>Instead of generic induction material, we rebuild the training from incident and near-miss records at your own site. The hazards discussed become ones participants genuinely recognise.</p><h2>Who This Is For</h2><p>Field workers, supervisors, and emergency response teams in high-risk industries.</p><h2>What You Receive</h2><ul><li>Analysis of two years of incident and near-miss records.</li><li>New induction material usable permanently for incoming workers.</li><li>Emergency drills using real site scenarios.</li><li>An emergency readiness report with recommendations.</li></ul>\"}','service-categories/fx5bqw3etxkvh658kjkkcbhwjbjam2llgtrus3yp.webp',4200000.00,0,NULL,'{\"id\":null}','{\"id\":\"4 hari (32 jam)\",\"en\":\"4 days (32 hours)\"}','Di lokasi klien','offline',35,23,1,0,10,1,NULL,NULL,'2026-09-05 02:00:00','2026-09-14 08:29:05');
