INSERT INTO `settings` (`id`, `group`, `key`, `value`, `type`, `created_at`, `updated_at`) VALUES (1,'localization','default_locale','id','text','2026-09-14 07:41:53','2026-09-14 07:41:53'),(2,'localization','available_locales','[\"id\",\"en\"]','json','2026-09-14 07:41:53','2026-09-14 07:41:53'),(3,'partnership','partnership_intro','{\"id\":\"Keterangan program kemitraan PT Delta Tiga Enam (in-house corporate training).\",\"en\":\"Description of PT Delta Tiga Enam corporate partnership program (in-house corporate training).\"}','json','2026-09-14 07:41:53','2026-09-14 07:41:53'),(4,'partnership','partnership_billing_mode','invoice','text','2026-09-14 07:41:53','2026-09-14 07:41:53'),(5,'general','site_name','PT Delta Tiga Enam','text','2026-09-14 07:41:53','2026-09-14 07:41:53'),(6,'general','site_email','info@deltatigaenam.com','text','2026-09-14 07:41:53','2026-09-14 07:41:53'),(7,'general','site_phone','021-5890 5002','text','2026-09-14 07:41:53','2026-09-14 07:41:53'),(8,'general','linkedin_url','https://linkedin.com/company/deltatigaenam','text','2026-09-14 07:41:53','2026-09-14 07:41:53'),(9,'general','company_tagline','{\"id\":\"Mitra strategis dalam transformasi human capital berkelanjutan.\",\"en\":\"A strategic partner in sustainable human capital transformation.\"}','json','2026-09-14 07:41:53','2026-09-14 07:41:53'),(10,'general','company_about','{\"id\":\"PT Delta Tiga Enam adalah lembaga pelatihan dan penyelenggara sertifikasi profesi yang membantu perusahaan dan individu meningkatkan kompetensi melalui pelatihan, konsultasi manajemen, pengelolaan human capital, dan layanan headhunter yang terintegrasi.\",\"en\":\"PT Delta Tiga Enam is a training institution and professional certification provider that helps companies and individuals improve competencies through integrated training, management consulting, human capital management, and headhunter services.\"}','json','2026-09-14 07:41:53','2026-09-14 07:41:53'),(11,'general','company_vision','{\"id\":\"Menjadi mitra strategis dalam transformasi human capital berkelanjutan.\",\"en\":\"To become a strategic partner in sustainable human capital transformation.\"}','json','2026-09-14 07:41:53','2026-09-14 07:41:53'),(12,'topbar','topbar_active','1','text','2026-09-14 08:15:55','2026-09-14 08:15:55'),(13,'topbar','topbar_promo_active','1','text','2026-09-14 08:15:55','2026-09-14 08:15:55'),(14,'topbar','topbar_promo_text','{\"id\":\"Promo Sertifikasi Ahli K3 Umum\",\"en\":\"General Safety Expert Certification Promo\"}','json','2026-09-14 08:15:55','2026-09-14 08:22:50'),(15,'topbar','topbar_promo_price_old','Rp 12.500.000','text','2026-09-14 08:15:55','2026-09-14 08:22:50'),(16,'topbar','topbar_promo_price_new','Rp 8.500.000','text','2026-09-14 08:15:55','2026-09-14 08:22:50'),(17,'topbar','topbar_promo_note','{\"id\":\"kuota terbatas bulan ini\",\"en\":\"limited quota this month\"}','json','2026-09-14 08:15:55','2026-09-14 08:15:55'),(18,'topbar','topbar_promo_cta','{\"id\":\"Lihat Program\",\"en\":\"View Program\"}','json','2026-09-14 08:15:55','2026-09-14 08:15:55'),(19,'topbar','topbar_promo_link','/layanan/sertifikasi-bnsp-ahli-k3-umum#daftar','text','2026-09-14 08:15:55','2026-09-14 08:29:05'),(20,'topbar','topbar_agenda_active','1','text','2026-09-14 08:15:55','2026-09-14 08:15:55'),(21,'topbar','topbar_agenda_text','{\"id\":\"Pelatihan & sertifikasi terbaru, lihat jadwal terdekat\",\"en\":\"Latest training & certification, see the upcoming schedule\"}','json','2026-09-14 08:15:55','2026-09-14 16:15:26'),(22,'topbar','topbar_agenda_cta','{\"id\":\"Lihat Agenda\",\"en\":\"View Agenda\"}','json','2026-09-14 08:15:55','2026-09-14 08:15:55'),(23,'topbar','topbar_agenda_link','','text','2026-09-14 08:15:55','2026-09-14 08:15:55'),(24,'stats','hero_stat_1_value','500+','text','2026-09-14 08:15:55','2026-09-14 08:15:55'),(25,'stats','hero_stat_1_label','{\"id\":\"Profesional Terlatih\",\"en\":\"Professionals Trained\"}','json','2026-09-14 08:15:56','2026-09-14 08:15:56'),(26,'stats','hero_stat_2_value','98%','text','2026-09-14 08:15:56','2026-09-14 08:15:56'),(27,'stats','hero_stat_2_label','{\"id\":\"Kepuasan Klien\",\"en\":\"Client Satisfaction\"}','json','2026-09-14 08:15:56','2026-09-14 08:15:56'),(28,'stats','hero_stat_3_value','10+','text','2026-09-14 08:15:56','2026-09-14 08:15:56'),(29,'stats','hero_stat_3_label','{\"id\":\"Tahun Pengalaman\",\"en\":\"Years Experience\"}','json','2026-09-14 08:15:56','2026-09-14 08:15:56'),(30,'stats','about_stat_1_value','10+','text','2026-09-14 08:15:56','2026-09-14 08:15:56'),(31,'stats','about_stat_1_label','{\"id\":\"Tahun pengalaman\",\"en\":\"Years of experience\"}','json','2026-09-14 08:15:56','2026-09-14 08:15:56'),(32,'stats','about_stat_2_value','500+','text','2026-09-14 08:15:56','2026-09-14 08:15:56'),(33,'stats','about_stat_2_label','{\"id\":\"Profesional terlatih\",\"en\":\"Professionals trained\"}','json','2026-09-14 08:15:56','2026-09-14 08:15:56'),(34,'stats','about_stat_3_value','50+','text','2026-09-14 08:15:56','2026-09-14 08:15:56'),(35,'stats','about_stat_3_label','{\"id\":\"Klien korporat\",\"en\":\"Corporate clients\"}','json','2026-09-14 08:15:56','2026-09-14 08:15:56'),(36,'stats','about_stat_4_value','20+','text','2026-09-14 08:15:56','2026-09-14 08:15:56'),(37,'stats','about_stat_4_label','{\"id\":\"Program sertifikasi\",\"en\":\"Certification programs\"}','json','2026-09-14 08:15:56','2026-09-14 08:15:56'),(38,'partnership','partnership_partners_title','{\"id\":\"Lembaga sertifikasi yang *bekerja sama* dengan kami\",\"en\":\"Certification bodies we *work with*\"}','json','2026-09-15 08:30:43','2026-09-15 08:32:04'),(39,'partnership','partnership_partners_desc','{\"id\":\"Pelatihan dan uji kompetensi kami dijalankan bersama lembaga sertifikasi profesi berlisensi BNSP. Sertifikat yang diterima karyawan Anda diakui secara nasional.\",\"en\":\"Our training and competency assessment run with BNSP-licensed certification bodies. The certificates your employees earn are recognised nationwide.\"}','json','2026-09-15 08:30:43','2026-09-15 08:32:04');
