INSERT INTO `testimonials` (`id`, `client_id`, `portfolio_id`, `author_name`, `author_position`, `author_company`, `author_photo`, `content`, `rating`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (1,NULL,1,'Andika Pratama','{\"id\":\"Direktur Human Capital\",\"en\":\"Human Capital Director\"}','PT Nusantara Jaya','testimonials/1mdr4fxgwyh2u7nl5b8b78uq4o60aubvvfzw8swg.webp','{\"id\":\"Yang membedakan Delta Tiga Enam adalah mereka turun langsung ke cabang, bukan menyusun struktur dari ruang rapat pusat. Hasilnya bisa kami jalankan tanpa banyak revisi di lapangan.\",\"en\":\"What set Delta Tiga Enam apart was that they went to the branches themselves rather than designing structure from a head-office meeting room. The result worked without much revision on the ground.\"}',5,1,1,1,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(2,NULL,1,'Siti Rahmawati','{\"id\":\"Manajer Pengembangan Organisasi\",\"en\":\"Organisational Development Manager\"}','PT Nusantara Jaya','testimonials/nmypbqkjrxfqxeuyais3frbwfciqgxlj1lwkbdcc.webp','{\"id\":\"Rotasi antarcabang yang dulu memakan enam pekan kini selesai dalam dua pekan. Perubahan sebesar itu terasa langsung oleh tim saya setiap bulan.\",\"en\":\"Inter-branch rotation that used to take six weeks now finishes in two. A change that size is felt by my team every single month.\"}',5,1,1,2,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(3,NULL,2,'Bambang Setiawan','{\"id\":\"Kepala Divisi Pembelajaran\",\"en\":\"Head of Learning Division\"}','Bank Sinar Mas','testimonials/qe5cyhuyuoe5v99nb0cyn8aknuagh2tgxuunuho7.webp','{\"id\":\"Materinya memakai kasus nyata dari catatan internal kami sendiri. Peserta tidak bisa menjawab dengan teori, karena kasusnya benar-benar mereka hadapi minggu lalu.\",\"en\":\"The material used real cases from our own internal records. Participants could not answer with theory, because the cases were ones they had faced the week before.\"}',5,1,1,3,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(4,NULL,2,'Dewi Kartika','{\"id\":\"Supervisor Operasional Cabang\",\"en\":\"Branch Operations Supervisor\"}','Bank Sinar Mas','testimonials/x7mpbuivqlbzu9nemwz6qtevsghhohwcenjsqlex.webp','{\"id\":\"Bagian percakapan sulit adalah yang paling saya butuhkan. Saya akhirnya punya cara menyampaikan koreksi tanpa membuat anggota tim menutup diri.\",\"en\":\"The difficult conversations section was what I needed most. I finally have a way to deliver correction without making team members shut down.\"}',4,1,1,4,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(5,NULL,3,'Hendra Wijaya','{\"id\":\"Komisaris\",\"en\":\"Commissioner\"}','Global Energi Group','testimonials/za3qoiubpsjay3qozqut0p3qff7lo4nkk63w9iam.webp','{\"id\":\"Pencarian sebelumnya berjalan delapan bulan tanpa hasil. Delta Tiga Enam mengisi dua posisi direksi dalam sebelas pekan, dan keduanya masih menjabat sampai hari ini.\",\"en\":\"Our previous search ran eight months with nothing. Delta Tiga Enam filled two board roles in eleven weeks, and both are still in post today.\"}',5,1,1,5,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(6,NULL,7,'Rina Marlina','{\"id\":\"Manajer Produksi\",\"en\":\"Production Manager\"}','PT Baja Perkasa','testimonials/1mdr4fxgwyh2u7nl5b8b78uq4o60aubvvfzw8swg.webp','{\"id\":\"Dua ratus empat puluh operator tersertifikasi tanpa satu jam pun produksi berhenti. Itu yang paling saya hargai. Mereka menyesuaikan jadwal uji dengan pola sif kami.\",\"en\":\"Two hundred and forty operators certified without a single production hour lost. That is what I valued most. They fitted the assessment schedule to our shift pattern.\"}',5,1,1,6,'2026-09-14 08:14:55','2026-09-14 16:15:28'),(7,NULL,7,'Agus Salim','{\"id\":\"Koordinator Lini Produksi\",\"en\":\"Production Line Coordinator\"}','PT Baja Perkasa','testimonials/nmypbqkjrxfqxeuyais3frbwfciqgxlj1lwkbdcc.webp','{\"id\":\"Kami diuji pada mesin yang kami operasikan sehari-hari, bukan di ruang kelas. Tim saya jauh lebih tenang menghadapinya.\",\"en\":\"We were assessed on the machines we run every day, not in a classroom. My team was far more at ease with it.\"}',4,0,1,7,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(8,NULL,8,'Yusuf Maulana','{\"id\":\"Direktur Operasional\",\"en\":\"Operations Director\"}','PT Cipta Mandiri Manufaktur','testimonials/qe5cyhuyuoe5v99nb0cyn8aknuagh2tgxuunuho7.webp','{\"id\":\"Mereka memangkas titik persetujuan, bukan memangkas orang. Waktu tanggap keluhan pelanggan kami turun dari sembilan hari menjadi tiga, tanpa satu pun PHK.\",\"en\":\"They cut approval points, not people. Our complaint response time fell from nine days to three with not a single redundancy.\"}',5,0,1,8,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(9,NULL,9,'Lestari Ningsih','{\"id\":\"Manajer SDM\",\"en\":\"HR Manager\"}','PT Tirta Anugerah','testimonials/x7mpbuivqlbzu9nemwz6qtevsghhohwcenjsqlex.webp','{\"id\":\"Untuk pertama kalinya keputusan promosi kami punya dasar yang bisa dijelaskan ke karyawan. Perdebatan soal keberpihakan langsung berhenti.\",\"en\":\"For the first time our promotion decisions had a basis we could explain to employees. The arguments about favouritism stopped immediately.\"}',5,0,1,9,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(10,NULL,10,'Fajar Nugroho','{\"id\":\"Kepala HSE\",\"en\":\"Head of HSE\"}','PT Lintas Samudra Energi','testimonials/za3qoiubpsjay3qozqut0p3qff7lo4nkk63w9iam.webp','{\"id\":\"Materinya disusun dari catatan insiden di lokasi kami sendiri. Pekerja mengenali setiap contoh yang dibahas, dan laporan nyaris celaka turun 41% pada semester berikutnya.\",\"en\":\"The material was built from incident records at our own site. Workers recognised every example discussed, and near-miss reports fell 41% the next half-year.\"}',5,0,1,10,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(11,NULL,11,'Ratna Sari Dewi','{\"id\":\"Kepala Divisi SDM\",\"en\":\"Head of HR Division\"}','Bank Pembangunan Daerah Jabar','testimonials/1mdr4fxgwyh2u7nl5b8b78uq4o60aubvvfzw8swg.webp','{\"id\":\"Sepertiga pemegang jabatan kunci kami akan pensiun dalam tiga tahun. Sekarang setiap posisi itu punya minimal dua kandidat pengganti yang sudah disiapkan.\",\"en\":\"A third of our key post-holders retire within three years. Now every one of those roles has at least two successor candidates already being prepared.\"}',5,0,1,11,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(12,NULL,12,'Teguh Prasetyo','{\"id\":\"Manajer Teknik\",\"en\":\"Engineering Manager\"}','PT Sumber Daya Elektrik','testimonials/nmypbqkjrxfqxeuyais3frbwfciqgxlj1lwkbdcc.webp','{\"id\":\"Delapan puluh lima teknisi bersertifikat tanpa perlu keluar kota sama sekali. Biaya sertifikasi angkatan berikutnya turun 38% karena tempat uji kini ada di lokasi kami.\",\"en\":\"Eighty-five technicians certified with no out-of-town travel at all. The next cohort cost 38% less because the assessment venue is now on our own site.\"}',5,0,1,12,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(13,NULL,15,'Maria Ulfa','{\"id\":\"Manajer Operasional Gerai\",\"en\":\"Store Operations Manager\"}','PT Ritel Maju Bersama','testimonials/qe5cyhuyuoe5v99nb0cyn8aknuagh2tgxuunuho7.webp','{\"id\":\"Standar layanannya diambil dari praktik gerai terbaik kami sendiri, jadi staf tidak merasa dipaksa mengikuti cara orang luar. Selisih nilai antargerai menyempit dari 34 poin ke 9.\",\"en\":\"The service standard came from our own best outlets, so staff did not feel forced into an outsider\'s way. The gap between outlets narrowed from 34 points to nine.\"}',4,0,1,13,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(14,NULL,16,'dr. Aditya Ramadhan','{\"id\":\"Direktur Pelayanan Medis\",\"en\":\"Medical Services Director\"}','RS Harapan Sehat','testimonials/x7mpbuivqlbzu9nemwz6qtevsghhohwcenjsqlex.webp','{\"id\":\"Uraian tugas ditulis dari apa yang benar-benar dikerjakan unit kami, bukan dari bagan di atas kertas. Temuan akreditasi soal ini tidak terulang lagi.\",\"en\":\"Job descriptions were written from what our units actually do, not from a chart on paper. The accreditation finding on this did not recur.\"}',5,0,1,14,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(15,NULL,17,'Iwan Kurniawan','{\"id\":\"Manajer Proyek\",\"en\":\"Project Manager\"}','PT Konstruksi Bumi Persada','testimonials/za3qoiubpsjay3qozqut0p3qff7lo4nkk63w9iam.webp','{\"id\":\"Dari empat orang Ahli K3 bersertifikat menjadi empat puluh satu. Kami akhirnya memenuhi syarat untuk ikut tender proyek besar yang selama ini tertutup.\",\"en\":\"From four certified safety experts to forty-one. We finally met the requirements for the large tenders that had been closed to us.\"}',5,0,1,15,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(16,NULL,18,'Nurul Hidayah','{\"id\":\"Manajer Rekrutmen\",\"en\":\"Recruitment Manager\"}','PT Tekstil Indah Permai','testimonials/1mdr4fxgwyh2u7nl5b8b78uq4o60aubvvfzw8swg.webp','{\"id\":\"Dua ribu empat ratus pelamar disaring menjadi tiga ratus operator dalam sembilan pekan. Tingkat bertahan kerja 92% setelah tiga bulan membuktikan seleksinya tepat.\",\"en\":\"Two thousand four hundred applicants screened down to three hundred operators in nine weeks. A 92% retention rate after three months proved the selection was right.\"}',4,0,1,16,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(17,NULL,19,'Rizky Firmansyah','{\"id\":\"Kepala Divisi Klaim\",\"en\":\"Head of Claims Division\"}','PT Asuransi Wira Sentosa','testimonials/nmypbqkjrxfqxeuyais3frbwfciqgxlj1lwkbdcc.webp','{\"id\":\"Pelatihannya tidak dimulai dari fitur sistem, tapi dari kekhawatiran karyawan. Itu yang membuat pemakaian naik dari 23% ke 88% dalam dua bulan.\",\"en\":\"The training started not with system features but with employees\' worries. That is what took usage from 23% to 88% in two months.\"}',5,0,1,17,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(18,NULL,20,'Surya Hadiningrat','{\"id\":\"Manajer Pengembangan SDM\",\"en\":\"HR Development Manager\"}','PT Pelabuhan Niaga Indonesia','testimonials/qe5cyhuyuoe5v99nb0cyn8aknuagh2tgxuunuho7.webp','{\"id\":\"Keluhan soal kejelasan karier turun dari peringkat satu ke peringkat tujuh dalam survei keterikatan. Karyawan kini bisa membaca sendiri syarat naik jenjang.\",\"en\":\"Career clarity complaints dropped from rank one to rank seven in our engagement survey. Employees can now read the advancement requirements themselves.\"}',5,0,1,18,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(19,NULL,21,'Bayu Anggara','{\"id\":\"Manajer Manajemen Risiko\",\"en\":\"Risk Management Manager\"}','PT Mineral Jaya Abadi','testimonials/x7mpbuivqlbzu9nemwz6qtevsghhohwcenjsqlex.webp','{\"id\":\"Sebelas catatan risiko departemen akhirnya menjadi satu daftar dengan skala yang sama. Direksi kami baru pertama kali melihat gambaran risiko perusahaan secara utuh.\",\"en\":\"Eleven departmental risk logs finally became one register on a single scale. Our board saw a whole-company risk picture for the first time.\"}',4,0,1,19,'2026-09-14 08:14:55','2026-09-14 08:14:55'),(20,NULL,23,'Dian Permatasari','{\"id\":\"Sekretaris Perusahaan\",\"en\":\"Corporate Secretary\"}','PT Properti Cendana Group','testimonials/za3qoiubpsjay3qozqut0p3qff7lo4nkk63w9iam.webp','{\"id\":\"Kandidat dengan pengalaman emiten di sektor properti sangat sedikit. Mereka memperluas pencarian ke sektor bersebelahan dan posisi terisi dalam tiga belas pekan.\",\"en\":\"Candidates with issuer experience in property are very few. They widened the search to adjacent sectors and the role was filled in thirteen weeks.\"}',5,0,1,20,'2026-09-14 08:14:55','2026-09-14 08:14:55');
